      'schema_sha256' => '0731e579878b56e80cd6227e54b9b2f36d44f73b890be39aee24f6b0460a1a8b',
      'source_file' => 'release:phase-4-script-v1/Phase4Script.schema.json',
      'json_schema_id' => 'https://superyacht.local/schemas/Phase4Script',
      'json_schema_dialect' => 'https://json-schema.org/draft/2020-12/schema',
