    "background_id": { "type": "string", "pattern": "^P[0-9]{2}$" },
    "design_id": { "type": "string", "pattern": "^(INT|EXT)[0-9]{2}$" },
    "tour_stop": { "type": ["integer", "null"], "minimum": 0 },
    "assumption": {
      "type": "object",
      "required": ["subject", "value", "reason"],
      "additionalProperties": false,
      "properties": {
        "subject": { "$ref": "#/$defs/text" },
        "value": { "$ref": "#/$defs/text" },
        "reason": { "$ref": "#/$defs/text" }
      }
    },
    "dimension": {
      "type": "object",
      "required": ["value", "basis"],
      "additionalProperties": false,
      "properties": {
        "value": { "anyOf": [{ "type": "null" }, { "type": "number", "exclusiveMinimum": 0 }] },
        "basis": { "enum": ["design", "derived", "production_assumption", "unknown"] }
      }
    },
    "size": {
      "type": "object",
      "required": ["length_m", "width_m", "height_m"],
      "additionalProperties": false,
      "properties": {
        "length_m": { "$ref": "#/$defs/dimension" },
        "width_m": { "$ref": "#/$defs/dimension" },
        "height_m": { "$ref": "#/$defs/dimension" }
      }
    },
    "fit": {
      "type": "object",
      "required": ["subject", "basis", "beats", "footprint", "overhead", "clear_height_m", "subject_size"],
      "additionalProperties": false,
      "properties": {
        "subject": { "enum": ["full_yacht", "component", "scale_model", "none"] },
        "basis": { "$ref": "#/$defs/text" },
        "beats": { "type": "array", "items": { "$ref": "#/$defs/beat_id" } },
        "footprint": { "enum": ["bounded", "open"] },
        "overhead": { "enum": ["constrained", "open", "unknown"] },
        "clear_height_m": { "$ref": "#/$defs/dimension" },
        "subject_size": { "anyOf": [{ "type": "null" }, { "$ref": "#/$defs/size" }] }
      }
    },
    "location": {
      "type": "object",
      "required": ["id", "name", "kind", "space", "dimensions", "fit", "surfaces", "fixed_equipment", "palette", "assumptions"],
      "additionalProperties": false,
      "properties": {
        "id": { "$ref": "#/$defs/location_id" },
        "name": { "$ref": "#/$defs/text" },
        "kind": { "enum": ["studio", "visualization_room", "test_tank", "construction_hall", "paint_hall", "launch", "sea", "anchorage", "other"] },
        "space": { "$ref": "#/$defs/text" },
        "dimensions": { "$ref": "#/$defs/size" },
        "fit": { "$ref": "#/$defs/fit" },
        "surfaces": { "type": "array", "minItems": 1, "items": { "$ref": "#/$defs/text" } },
        "fixed_equipment": { "$ref": "#/$defs/texts" },
        "palette": { "type": "array", "minItems": 1, "items": { "$ref": "#/$defs/hex" } },
        "assumptions": { "type": "array", "items": { "$ref": "#/$defs/assumption" } }
      }
    },
    "space_ref": {
      "anyOf": [
        {
          "type": "object",
          "required": ["kind", "id", "state"],
          "additionalProperties": false,
          "properties": {
            "kind": { "enum": ["location", "interior", "exterior"] },
            "id": { "type": "string", "pattern": "^(INT|EXT|LOC)[0-9]{2}$" },
            "state": { "anyOf": [{ "$ref": "#/$defs/state" }, { "type": "null" }] }
          }
        },
        { "type": "null" }
      ]
    },
    "evidence": {
      "type": "object",
      "required": ["beat", "tour_stop", "field", "quote"],
      "additionalProperties": false,
      "properties": {
        "beat": { "$ref": "#/$defs/beat_id" },
        "tour_stop": { "$ref": "#/$defs/tour_stop" },
        "field": { "enum": ["location", "visual", "action", "time_light", "purpose", "tour"] },
        "quote": { "$ref": "#/$defs/text" }
      }
    },
    "use": {
      "type": "object",
      "required": ["beat", "tour_stop", "part"],
      "additionalProperties": false,
      "properties": {
        "beat": { "$ref": "#/$defs/beat_id" },
        "tour_stop": { "$ref": "#/$defs/tour_stop" },
        "part": { "$ref": "#/$defs/text" }
      }
    },
    "condition": {
      "type": "object",
      "required": ["text", "limit"],
      "additionalProperties": false,
      "properties": {
        "text": { "$ref": "#/$defs/text" },
        "limit": { "$ref": "#/$defs/nullable_text" }
      }
    },
    "detail": {
      "type": "object",
      "required": ["text", "evidence", "assumption"],
      "additionalProperties": false,
      "properties": {
        "text": { "$ref": "#/$defs/text" },
        "evidence": { "anyOf": [{ "$ref": "#/$defs/evidence" }, { "type": "null" }] },
        "assumption": { "type": "boolean" }
      },
      "if": { "properties": { "assumption": { "const": false } } },
      "then": { "properties": { "evidence": { "type": "object" } } }
    },
    "light": {
      "type": "object",
      "required": ["description", "evidence"],
      "additionalProperties": false,
      "properties": {
        "description": { "$ref": "#/$defs/text" },
        "evidence": { "$ref": "#/$defs/evidence" }
      }
    },
    "design_ref": {
      "type": "object",
      "required": ["id", "quote"],
      "additionalProperties": false,
      "properties": {
        "id": { "type": "string", "pattern": "^N[0-9]{1,2}$" },
        "quote": { "$ref": "#/$defs/text" }
      }
    },
    "change": {
      "type": "object",
      "required": ["beats", "kind", "change", "keep"],
      "additionalProperties": false,
      "properties": {
        "beats": { "type": "array", "minItems": 1, "items": { "$ref": "#/$defs/beat_id" } },
        "kind": { "enum": ["light", "condition", "props", "layout"] },
        "change": { "$ref": "#/$defs/text" },
        "keep": { "$ref": "#/$defs/text" }
      }
    },
    "source": {
      "type": "object",
      "required": ["type", "id", "state", "evidence", "reason"],
      "additionalProperties": false,
      "properties": {
        "type": { "enum": ["script_id", "mapped_id", "location"] },
        "id": { "type": "string", "pattern": "^(INT|EXT|LOC)[0-9]{2}$" },
        "state": { "anyOf": [{ "$ref": "#/$defs/state" }, { "type": "null" }] },
        "evidence": { "type": "array", "items": { "$ref": "#/$defs/evidence" } },
        "reason": { "$ref": "#/$defs/nullable_text" }
      },
      "if": { "properties": { "type": { "const": "mapped_id" } } },
      "then": { "properties": { "evidence": { "minItems": 1 }, "reason": { "$ref": "#/$defs/text" } } }
    },
    "background": {
      "type": "object",
      "required": ["id", "name", "kind", "source", "uses", "sharing", "scope", "composition", "light", "condition", "details", "design_refs", "lighting_signature", "surroundings", "must_show", "avoid", "shot_changes", "assumptions"],
      "additionalProperties": false,
      "properties": {
        "id": { "$ref": "#/$defs/background_id" },
        "name": { "$ref": "#/$defs/text" },
        "kind": { "enum": ["location", "interior", "exterior"] },
        "source": { "$ref": "#/$defs/source" },
        "uses": { "type": "array", "minItems": 1, "items": { "$ref": "#/$defs/use" } },
        "sharing": { "$ref": "#/$defs/text" },
        "scope": { "$ref": "#/$defs/text" },
        "composition": { "$ref": "#/$defs/text" },
        "light": { "$ref": "#/$defs/light" },
        "condition": { "type": "array", "items": { "$ref": "#/$defs/condition" } },
        "details": { "type": "array", "items": { "$ref": "#/$defs/detail" } },
        "design_refs": { "type": "array", "items": { "$ref": "#/$defs/design_ref" } },
        "lighting_signature": { "type": "boolean" },
        "surroundings": { "$ref": "#/$defs/nullable_text" },
        "must_show": { "type": "array", "maxItems": 4, "items": { "$ref": "#/$defs/text" } },
        "avoid": { "$ref": "#/$defs/texts" },
        "shot_changes": { "type": "array", "items": { "$ref": "#/$defs/change" } },
        "assumptions": { "type": "array", "items": { "$ref": "#/$defs/assumption" } }
      },
      "allOf": [
        {
          "if": { "properties": { "kind": { "const": "location" } } },
          "then": {
            "properties": {
              "source": { "properties": { "type": { "const": "location" }, "id": { "pattern": "^LOC[0-9]{2}$" }, "state": { "type": "null" }, "evidence": { "maxItems": 0 } } },
              "design_refs": { "maxItems": 0 },
              "lighting_signature": { "const": false }
            }
          }
        },
        {
          "if": { "properties": { "kind": { "const": "interior" } } },
          "then": {
            "properties": {
              "source": { "properties": { "type": { "enum": ["script_id", "mapped_id"] }, "id": { "pattern": "^INT[0-9]{2}$" }, "state": { "$ref": "#/$defs/state" } } }
            }
          }
        },
        {
          "if": { "properties": { "kind": { "const": "exterior" } } },
          "then": {
            "properties": {
              "source": { "properties": { "type": { "enum": ["script_id", "mapped_id"] }, "id": { "pattern": "^EXT[0-9]{2}$" }, "state": { "type": "null" } } }
            }
          }
        }
      ]
    },
    "unplated": {
      "type": "object",
      "required": ["beat", "tour_stop", "space", "part", "reason", "handoff"],
      "additionalProperties": false,
      "properties": {
        "beat": { "$ref": "#/$defs/beat_id" },
        "tour_stop": { "$ref": "#/$defs/tour_stop" },
        "space": { "$ref": "#/$defs/space_ref" },
        "part": { "$ref": "#/$defs/text" },
        "reason": { "$ref": "#/$defs/text" },
        "handoff": { "$ref": "#/$defs/text" }
      }
    },
    "unresolved": {
      "type": "object",
      "required": ["beat", "tour_stop", "space", "part", "text", "evidence", "candidates", "reason"],
      "additionalProperties": false,
      "properties": {
        "beat": { "$ref": "#/$defs/beat_id" },
        "tour_stop": { "$ref": "#/$defs/tour_stop" },
        "space": { "$ref": "#/$defs/space_ref" },
        "part": { "$ref": "#/$defs/text" },
        "text": { "$ref": "#/$defs/text" },
        "evidence": { "type": "array", "minItems": 1, "items": { "$ref": "#/$defs/evidence" } },
        "candidates": { "type": "array", "items": { "$ref": "#/$defs/design_id" } },
        "reason": { "$ref": "#/$defs/text" }
      }
    },
    "conflict": {
      "type": "object",
      "required": ["beat", "background", "field", "design", "script", "note"],
      "additionalProperties": false,
      "properties": {
        "beat": { "anyOf": [{ "$ref": "#/$defs/beat_id" }, { "type": "null" }] },
        "background": { "anyOf": [{ "$ref": "#/$defs/background_id" }, { "type": "null" }] },
        "field": { "$ref": "#/$defs/text" },
        "design": { "$ref": "#/$defs/text" },
        "script": { "$ref": "#/$defs/text" },
        "note": { "$ref": "#/$defs/text" }
      }
    },
    "continuity": {
      "type": "object",
      "required": ["backgrounds", "beats", "requirement"],
      "additionalProperties": false,
      "properties": {
        "backgrounds": { "type": "array", "minItems": 1, "items": { "$ref": "#/$defs/background_id" } },
        "beats": { "type": "array", "minItems": 2, "items": { "$ref": "#/$defs/beat_id" } },
        "requirement": { "$ref": "#/$defs/text" }
      }
    },
    "data": {
      "type": "object",
      "required": ["locations", "backgrounds", "unplated", "unresolved", "conflicts", "continuity"],
      "additionalProperties": false,
      "properties": {
        "locations": { "type": "array", "items": { "$ref": "#/$defs/location" } },
        "backgrounds": { "type": "array", "minItems": 1, "items": { "$ref": "#/$defs/background" } },
        "unplated": { "type": "array", "items": { "$ref": "#/$defs/unplated" } },
        "unresolved": { "type": "array", "items": { "$ref": "#/$defs/unresolved" } },
        "conflicts": { "type": "array", "items": { "$ref": "#/$defs/conflict" } },
        "continuity": { "type": "array", "items": { "$ref": "#/$defs/continuity" } }
      }
    }
  }
}
