      'schema_sha256' => '4b57f969010567d41ceff488661b0f4971fdbda3dcd4bce0081d56dfe6480be0',
      'source_file' => 'release:phase-3-design-v2/Phase3Design.schema.json',
      'json_schema_id' => 'https://superyacht.local/schemas/Phase3Design',
      'json_schema_dialect' => 'https://json-schema.org/draft/2020-12/schema',
      'dependencies' => '[]',
