    21 => 
    array (
      'id' => 'a31b0f46-94cf-4724-a033-b4fe0e2246a8',
      'namespace' => 'superyacht',
      'schema_key' => 'Phase4Script',
      'version' => '2.1.0',
      'name' => 'Phase4Script (phase4-script-v2, character anchors within their word limit)',
      'schema_content' => '{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://superyacht.local/schemas/Phase4Script",
  "title": "Phase4Script (phase4-script-v2, character anchors within their word limit)",
  "x-word-limits": {
    "anchors.character.*": 100
  },
  "type": "object",
  "required": ["format", "phase", "project_id", "prompt_version", "status", "data", "flags", "notes"],
  "additionalProperties": false,
  "properties": {
    "format": {"const": "phase4-script-v2"},
    "phase": {"const": "4"},
    "project_id": {"$ref": "#/$defs/text"},
    "prompt_version": {"$ref": "#/$defs/text"},
    "status": {"enum": ["ok", "partial", "fail"]},
    "data": {"type": "object"},
    "flags": {"type": "array", "items": {"$ref": "#/$defs/text"}},
    "notes": {"type": "string"}
  },
  "allOf": [
    {
      "if": {"properties": {"status": {"const": "fail"}}},
      "then": {"properties": {"data": {"maxProperties": 0}, "flags": {"minItems": 1}}},
      "else": {"properties": {"data": {"$ref": "#/$defs/data"}}}
    },
    {
      "if": {"properties": {"status": {"const": "partial"}}},
      "then": {"properties": {"flags": {"minItems": 1}}}
    }
  ],
  "$defs": {
    "text": {"type": "string", "minLength": 1, "pattern": "\\\\S"},
    "beat_id": {"enum": ["B0", "B1", "B2", "B3", "B4", "B5", "B6", "B7", "B8", "B9", "B10", "B11", "B12", "B13", "B14", "B15", "B16"]},
    "data": {
      "type": "object",
      "required": ["story", "anchors", "script"],
      "additionalProperties": false,
      "properties": {
        "story": {"$ref": "#/$defs/story"},
        "anchors": {
          "type": "object",
          "required": ["character"],
          "additionalProperties": false,
          "properties": {
            "character": {
              "type": "object",
              "required": ["HANDS", "CREW", "CAPTAIN"],
              "additionalProperties": false,
              "properties": {"HANDS": {"$ref": "#/$defs/text"}, "CREW": {"$ref": "#/$defs/text"}, "CAPTAIN": {"$ref": "#/$defs/text"}}
            }
          }
        },
        "script": {"$ref": "#/$defs/script"}
      }
    },
    "story": {
      "type": "object",
      "required": ["type", "spine", "central_question", "question_card", "stakes", "obstacles", "countdown", "loops", "motifs", "money_shots", "notes"],
      "additionalProperties": false,
      "properties": {
        "type": {"enum": ["A", "B", "C", "D", "E"]},
        "spine": {"$ref": "#/$defs/text"},
        "central_question": {"anyOf": [{"type": "null"}, {"$ref": "#/$defs/text"}]},
        "question_card": {"anyOf": [{"type": "null"}, {"$ref": "#/$defs/text"}]},
        "stakes": {"anyOf": [{"type": "null"}, {"$ref": "#/$defs/text"}]},
        "obstacles": {"type": "array", "items": {"$ref": "#/$defs/obstacle"}},
        "countdown": {"anyOf": [{"type": "null"}, {"$ref": "#/$defs/text"}]},
        "loops": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["id", "plant", "payoff"],
            "additionalProperties": false,
            "properties": {"id": {"type": "string", "pattern": "^L[1-9][0-9]*$"}, "plant": {"$ref": "#/$defs/beat_id"}, "payoff": {"$ref": "#/$defs/beat_id"}}
          }
        },
        "motifs": {
          "type": "object",
          "required": ["visual", "sound", "first_last_rhyme"],
          "additionalProperties": false,
          "properties": {"visual": {"$ref": "#/$defs/text"}, "sound": {"$ref": "#/$defs/text"}, "first_last_rhyme": {"$ref": "#/$defs/text"}}
        },
        "money_shots": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["beat", "text", "from_suggestions"],
            "additionalProperties": false,
            "properties": {"beat": {"$ref": "#/$defs/beat_id"}, "text": {"$ref": "#/$defs/text"}, "from_suggestions": {"type": "boolean"}}
          }
        },
        "notes": {"type": "string"}
      },
      "if": {"properties": {"type": {"const": "E"}}},
      "then": {
        "properties": {"obstacles": {"maxItems": 0}},
        "oneOf": [
          {"properties": {"central_question": {"type": "null"}, "question_card": {"type": "null"}, "stakes": {"type": "null"}}},
          {"properties": {"central_question": {"type": "string"}, "question_card": {"type": "string"}, "stakes": {"type": "string"}}}
        ]
      },
      "else": {
        "properties": {"central_question": {"type": "string"}, "question_card": {"type": "string"}, "stakes": {"type": "string"}}
      }
    },
    "obstacle": {
      "type": "object",
      "required": ["id", "beat", "label", "problem", "sign", "action", "proof"],
      "additionalProperties": false,
      "properties": {
        "id": {"type": "string", "pattern": "^O[1-9][0-9]*$"},
        "beat": {"$ref": "#/$defs/beat_id"},
        "label": {"const": "[CONCEPT STORY]"},
        "problem": {"$ref": "#/$defs/text"},
        "sign": {"$ref": "#/$defs/text"},
        "action": {"$ref": "#/$defs/text"},
        "proof": {"$ref": "#/$defs/text"}
      }
    },
    "script": {
      "type": "object",
      "required": ["logline", "beats", "tour", "text_cards", "music_brief", "sfx_plan"],
      "additionalProperties": false,
      "properties": {
        "logline": {"$ref": "#/$defs/text"},
        "beats": {"type": "array", "minItems": 17, "maxItems": 17, "items": {"$ref": "#/$defs/beat"}},
        "tour": {
          "type": "object",
          "required": ["beat", "stops"],
          "additionalProperties": false,
          "properties": {
            "beat": {"const": "B14"},
            "stops": {"type": "array", "minItems": 1, "items": {"$ref": "#/$defs/tour_stop"}}
          }
        },
        "text_cards": {"type": "array", "items": {"$ref": "#/$defs/text_card"}},
        "music_brief": {
          "type": "object",
          "required": ["length", "bpm", "sections"],
          "additionalProperties": false,
          "properties": {
            "length": {"type": "number", "exclusiveMinimum": 0},
            "bpm": {"type": "array", "minItems": 2, "maxItems": 2, "items": {"type": "number", "exclusiveMinimum": 0}},
            "sections": {"type": "array", "minItems": 1, "items": {"$ref": "#/$defs/text"}}
          }
        },
        "sfx_plan": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["beat", "sfx"],
            "additionalProperties": false,
            "properties": {"beat": {"$ref": "#/$defs/beat_id"}, "sfx": {"type": "array", "minItems": 1, "items": {"$ref": "#/$defs/text"}}}
          }
        }
      }
    },
    "tour_stop": {
      "type": "object",
      "required": ["source_id", "sec", "visual", "match_bare_beat"],
      "additionalProperties": false,
      "properties": {
        "source_id": {"type": "string", "pattern": "^(INT|EXT)[0-9]{2}$"},
        "sec": {"type": "number", "exclusiveMinimum": 0, "maximum": 1.5},
        "visual": {"$ref": "#/$defs/text"},
        "match_bare_beat": {"anyOf": [{"type": "null"}, {"$ref": "#/$defs/beat_id"}]}
      }
    },
    "beat": {
      "type": "object",
      "required": ["id", "act", "target_sec", "purpose", "visual", "sound", "emotion", "bs", "rooms", "reveal", "location", "time_light", "camera_family", "action", "progress", "link", "adaptation"],
      "additionalProperties": false,
      "properties": {
        "id": {"$ref": "#/$defs/beat_id"},
        "act": {"enum": ["A1", "A2", "A3", "A4"]},
        "target_sec": {"type": "number", "exclusiveMinimum": 0},
        "purpose": {"$ref": "#/$defs/text"},
        "visual": {"$ref": "#/$defs/text"},
        "sound": {"$ref": "#/$defs/text"},
        "emotion": {"type": "integer", "minimum": 1, "maximum": 10},
        "bs": {"type": "string", "pattern": "^BS(0[1-9]|1[0-2])$"},
        "rooms": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["id", "set_state"],
            "additionalProperties": false,
            "properties": {"id": {"type": "string", "pattern": "^INT[0-9]{2}$"}, "set_state": {"enum": ["bare", "fitout", "finished"]}}
          }
        },
        "reveal": {"enum": ["H1", "H2", "H3", "H4", "H5"]},
        "location": {"$ref": "#/$defs/text"},
        "time_light": {"$ref": "#/$defs/text"},
        "camera_family": {"enum": ["beam", "aerial", "tracking", "from_deck", "macro", "interior"]},
        "action": {"$ref": "#/$defs/text"},
        "progress": {"type": "boolean"},
        "link": {"anyOf": [{"type": "null"}, {"$ref": "#/$defs/text"}]},
        "adaptation": {"anyOf": [{"type": "null"}, {"$ref": "#/$defs/text"}]}
      },
      "allOf": [
        {"if": {"properties": {"id": {"enum": ["B0", "B1", "B2", "B3", "B4", "B5"]}}}, "then": {"properties": {"act": {"const": "A1"}}}},
        {"if": {"properties": {"id": {"enum": ["B6", "B7", "B8", "B9", "B10"]}}}, "then": {"properties": {"act": {"const": "A2"}}}},
        {"if": {"properties": {"id": {"enum": ["B11", "B12"]}}}, "then": {"properties": {"act": {"const": "A3"}}}},
        {"if": {"properties": {"id": {"enum": ["B13", "B14", "B15", "B16"]}}}, "then": {"properties": {"act": {"const": "A4"}}}},
        {"if": {"properties": {"id": {"const": "B16"}}}, "then": {"properties": {"reveal": {"const": "H5"}}}, "else": {"properties": {"reveal": {"not": {"const": "H5"}}}}},
        {"if": {"properties": {"id": {"const": "B0"}}}, "then": {"properties": {"link": {"type": "null"}}}, "else": {"properties": {"link": {"type": "string"}}}},
        {"if": {"properties": {"act": {"not": {"const": "A4"}}}}, "then": {"properties": {"rooms": {"items": {"properties": {"set_state": {"enum": ["bare", "fitout"]}}}}}}}
      ]
    },
    "text_card": {
      "type": "object",
      "required": ["beat", "text", "type", "sec"],
      "additionalProperties": false,
      "properties": {
        "beat": {"$ref": "#/$defs/beat_id"},
        "text": {"$ref": "#/$defs/text"},
        "type": {"enum": ["STAGE", "SPEC", "NAME", "QUESTION", "DISCLAIMER", "END"]},
        "sec": {"type": "number", "minimum": 1.5}
      },
      "if": {"properties": {"type": {"const": "SPEC"}}},
      "then": {"properties": {"text": {"pattern": "· CONCEPT$"}}}
    }
  }
}
