      'schema_sha256' => '9fa23a71eefa53450591ff6d638448f172cde5e4a56931343c80300171415787',
      'source_file' => 'release:phase-3-design-v3/Phase3Design.schema.json',
      'json_schema_id' => 'https://superyacht.local/schemas/Phase3Design',
      'json_schema_dialect' => 'https://json-schema.org/draft/2020-12/schema',
