    array (
      'id' => 'a31cbb51-4c3e-408f-b10c-33a32b9d8387',
      'namespace' => 'superyacht',
      'schema_key' => 'Phase1Evidence',
      'version' => '2.0.0',
      'name' => 'Phase 1 — inspiration evidence (phase1-evidence-v2)',
      'schema_content' => '{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://superyacht.local/schemas/Phase1Evidence",
  "title": "Phase 1 — inspiration evidence (phase1-evidence-v2)",
  "description": "One answer of Phase 1: the subject the article is about, what it states about that subject with verbatim evidence for every value, the open source issues and the eight self-checks. Evidence is checked against the article; nothing here is verified as true outside the article.",
  "type": "object",
  "additionalProperties": false,
  "required": ["format", "subject", "inspiration", "issues", "self_check"],
  "properties": {
    "format": { "const": "phase1-evidence-v2" },
    "subject": {
      "type": "object",
      "additionalProperties": false,
      "required": ["article_kind", "status", "primary", "basis", "others"],
      "properties": {
        "article_kind": { "enum": ["single_yacht", "multiple_yachts", "product_line", "not_a_yacht"] },
        "status": { "enum": ["identified", "ambiguous", "none"] },
        "primary": { "type": ["string", "null"], "minLength": 1 },
        "basis": { "type": "array", "items": { "$ref": "#/$defs/evidence" } },
        "others": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": ["name", "relation", "evidence"],
            "properties": {
              "name": { "type": "string", "minLength": 1 },
              "relation": { "enum": ["predecessor", "sister", "comparison", "other"] },
              "evidence": { "$ref": "#/$defs/evidenceList" }
            }
          }
        }
      },
      "allOf": [
        { "if": { "properties": { "status": { "const": "identified" } } }, "then": { "properties": { "primary": { "type": "string" }, "basis": { "minItems": 1 } } } },
        { "if": { "properties": { "status": { "const": "ambiguous" } } }, "then": { "properties": { "primary": { "type": "null" } } } },
        { "if": { "properties": { "status": { "const": "none" } } }, "then": { "properties": { "primary": { "type": "null" } } } },
        { "if": { "properties": { "article_kind": { "const": "not_a_yacht" } } }, "then": { "properties": { "status": { "const": "none" } } } }
      ]
    },
    "inspiration": {
      "type": "object",
      "additionalProperties": false,
      "required": ["source_identity", "exterior", "interior", "technology", "scale", "intent", "visuals", "claims"],
      "properties": {
        "source_identity": {
          "type": "object",
          "additionalProperties": false,
          "required": ["name", "builder", "designers", "silhouette", "bow", "superstructure", "colors", "signatures"],
          "properties": {
            "name": { "$ref": "#/$defs/quoted" },
            "builder": { "$ref": "#/$defs/quoted" },
            "designers": { "$ref": "#/$defs/quotedList" },
            "silhouette": { "$ref": "#/$defs/quoted" },
            "bow": { "$ref": "#/$defs/quoted" },
            "superstructure": { "$ref": "#/$defs/quoted" },
            "colors": { "$ref": "#/$defs/quoted" },
            "signatures": { "type": "array", "items": { "allOf": [{ "$ref": "#/$defs/item" }, { "properties": { "id": { "pattern": "^S[0-9]{2,}$" } } }] } }
          }
        },
        "exterior": { "type": "array", "items": { "allOf": [{ "$ref": "#/$defs/item" }, { "properties": { "id": { "pattern": "^X[0-9]{2,}$" } } }] } },
        "interior": { "type": "array", "items": { "allOf": [{ "$ref": "#/$defs/item" }, { "properties": { "id": { "pattern": "^I[0-9]{2,}$" } } }] } },
        "technology": { "type": "array", "items": { "allOf": [{ "$ref": "#/$defs/item" }, { "properties": { "id": { "pattern": "^T[0-9]{2,}$" } } }] } },
        "scale": {
          "type": "object",
          "additionalProperties": false,
          "required": ["loa", "lwl", "beam", "draft", "decks", "layout", "guests", "crew", "gross_tonnage", "interior_volume"],
          "properties": {
            "loa": { "$ref": "#/$defs/measure" },
            "lwl": { "$ref": "#/$defs/measure" },
            "beam": { "$ref": "#/$defs/measure" },
            "draft": { "$ref": "#/$defs/measure" },
            "decks": { "$ref": "#/$defs/measure" },
            "layout": { "$ref": "#/$defs/measure" },
            "guests": { "$ref": "#/$defs/measure" },
            "crew": { "$ref": "#/$defs/measure" },
            "gross_tonnage": { "$ref": "#/$defs/measure" },
            "interior_volume": { "$ref": "#/$defs/measure" }
          }
        },
        "intent": {
          "oneOf": [
            { "type": "null" },
            {
              "type": "object",
              "additionalProperties": false,
              "required": ["text", "evidence"],
              "properties": {
                "text": { "type": "string", "minLength": 1 },
                "evidence": { "$ref": "#/$defs/evidenceList" }
              }
            }
          ]
        },
        "visuals": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": ["id", "description", "evidence"],
            "properties": {
              "id": { "type": "string", "pattern": "^V[0-9]{2,}$" },
              "description": { "type": "string", "minLength": 1 },
              "evidence": { "type": "array", "minItems": 1, "items": { "allOf": [{ "$ref": "#/$defs/evidence" }, { "properties": { "source": { "const": "caption" } } }] } }
            }
          }
        },
        "claims": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": ["id", "claim", "evidence"],
            "properties": {
              "id": { "type": "string", "pattern": "^C[0-9]{2,}$" },
              "claim": { "type": "string", "minLength": 1 },
              "evidence": { "$ref": "#/$defs/evidenceList" }
            }
          }
        }
      }
    },
    "issues": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["kind", "field", "message", "evidence"],
        "properties": {
          "kind": { "enum": ["missing", "ambiguous", "conflict"] },
          "field": { "type": "string", "pattern": "^(subject(\\\\.(article_kind|status|primary|basis|others))?|inspiration\\\\.intent|inspiration\\\\.scale\\\\.(loa|lwl|beam|draft|decks|layout|guests|crew|gross_tonnage|interior_volume)|inspiration\\\\.source_identity\\\\.(name|builder|designers|silhouette|bow|superstructure|colors|signatures(\\\\.S[0-9]{2,})?)|inspiration\\\\.exterior(\\\\.X[0-9]{2,})?|inspiration\\\\.interior(\\\\.I[0-9]{2,})?|inspiration\\\\.technology(\\\\.T[0-9]{2,})?|inspiration\\\\.visuals(\\\\.V[0-9]{2,})?|inspiration\\\\.claims(\\\\.C[0-9]{2,})?)$" },
          "message": { "type": "string", "minLength": 1 },
          "evidence": { "type": "array", "items": { "$ref": "#/$defs/evidence" } }
        },
        "allOf": [
          { "if": { "properties": { "kind": { "const": "conflict" } } }, "then": { "properties": { "evidence": { "minItems": 1 } } } }
        ]
      }
    },
    "self_check": {
      "type": "array",
      "minItems": 8,
      "prefixItems": [
        { "allOf": [{ "$ref": "#/$defs/check" }, { "properties": { "check": { "const": "subject" } } }] },
        { "allOf": [{ "$ref": "#/$defs/check" }, { "properties": { "check": { "const": "evidence" } } }] },
        { "allOf": [{ "$ref": "#/$defs/check" }, { "properties": { "check": { "const": "completeness" } } }] },
        { "allOf": [{ "$ref": "#/$defs/check" }, { "properties": { "check": { "const": "no_inference" } } }] },
        { "allOf": [{ "$ref": "#/$defs/check" }, { "properties": { "check": { "const": "no_duplicates" } } }] },
        { "allOf": [{ "$ref": "#/$defs/check" }, { "properties": { "check": { "const": "measurements" } } }] },
        { "allOf": [{ "$ref": "#/$defs/check" }, { "properties": { "check": { "const": "captions" } } }] },
        { "allOf": [{ "$ref": "#/$defs/check" }, { "properties": { "check": { "const": "contract" } } }] }
      ],
      "items": false
    }
  },
  "allOf": [
    { "if": { "required": ["self_check"], "properties": { "self_check": { "contains": { "required": ["result"], "properties": { "result": { "const": "open" } } } } } }, "then": { "properties": { "issues": { "minItems": 1 } } } },
    { "if": { "required": ["subject"], "properties": { "subject": { "required": ["status"], "properties": { "status": { "const": "ambiguous" } } } } }, "then": { "properties": { "issues": { "contains": { "required": ["kind", "field"], "properties": { "kind": { "const": "ambiguous" }, "field": { "pattern": "^subject(\\\\.|$)" } } } } } } }
  ],
  "$defs": {
    "source": { "enum": ["headline", "body", "caption", "table", "metadata"] },
    "evidence": {
      "type": "object",
      "additionalProperties": false,
      "required": ["quote", "source"],
      "properties": {
        "quote": { "type": "string", "minLength": 1 },
        "source": { "$ref": "#/$defs/source" }
      }
    },
    "evidenceList": { "type": "array", "minItems": 1, "items": { "$ref": "#/$defs/evidence" } },
    "quoted": {
      "oneOf": [
        { "type": "null" },
        {
          "type": "object",
          "additionalProperties": false,
          "required": ["value", "evidence"],
          "properties": {
            "value": { "type": "string", "minLength": 1 },
            "evidence": { "$ref": "#/$defs/evidenceList" }
          }
        }
      ]
    },
    "quotedList": {
      "oneOf": [
        { "type": "null" },
        {
          "type": "object",
          "additionalProperties": false,
          "required": ["value", "evidence"],
          "properties": {
            "value": { "type": "array", "minItems": 1, "items": { "type": "string", "minLength": 1 } },
            "evidence": { "$ref": "#/$defs/evidenceList" }
          }
        }
      ]
    },
    "item": {
      "type": "object",
      "additionalProperties": false,
      "required": ["id", "feature", "applies_to", "evidence"],
      "properties": {
        "id": { "type": "string" },
        "feature": { "type": "string", "minLength": 1 },
        "applies_to": { "enum": ["primary", "product_line"] },
        "evidence": { "$ref": "#/$defs/evidenceList" }
      }
    },
    "measure": {
      "oneOf": [
        { "type": "null" },
        {
          "type": "object",
          "additionalProperties": false,
          "required": ["value", "applies_to", "evidence"],
          "properties": {
            "value": { "type": "string", "minLength": 1 },
            "applies_to": { "enum": ["primary", "product_line"] },
            "evidence": { "$ref": "#/$defs/evidenceList" }
          }
        }
      ]
    },
    "check": {
      "type": "object",
      "additionalProperties": false,
      "required": ["check", "result", "note"],
      "properties": {
        "check": { "type": "string" },
        "result": { "enum": ["passed", "open"] },
        "note": { "type": "string" }
      },
      "allOf": [
        { "if": { "properties": { "result": { "const": "open" } } }, "then": { "properties": { "note": { "pattern": "\\\\S" } } } }
      ]
    }
  }
}
