    array (
      'id' => 'a31ce464-28ec-4883-acb4-226b0450df7e',
      'namespace' => 'superyacht',
      'schema_key' => 'Phase2Dna',
      'version' => '2.0.0',
      'name' => 'Phase 2 — design DNA (phase2-dna-v2)',
      'schema_content' => '{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://superyacht.local/schemas/Phase2Dna",
  "title": "Phase 2 — design DNA (phase2-dna-v2)",
  "description": "One answer of Phase 2: the brief for one new yacht concept that departs from the Phase 1 source, and the ten self-checks the writer ran and repaired before answering. The self-checks match the brief against the prompt; they are not proof of novelty and not an engineering approval.",
  "type": "object",
  "additionalProperties": false,
  "required": ["format", "dna", "self_check"],
  "properties": {
    "format": { "const": "phase2-dna-v2" },
    "dna": {
      "type": "object",
      "additionalProperties": false,
      "required": ["theme", "departures", "innovations", "silhouette", "must_avoid", "hero_moment", "emotion"],
      "properties": {
        "theme": { "$ref": "#/$defs/text" },
        "departures": {
          "type": "array",
          "minItems": 3,
          "maxItems": 5,
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": ["id", "from_id", "method", "result"],
            "properties": {
              "id": { "type": "string", "pattern": "^D[1-5]$" },
              "from_id": { "type": "string", "minLength": 1 },
              "method": { "type": "string", "pattern": "^(CROSS-DOMAIN|INVERT|MERGE|RELOCATE|SCALE SHIFT|SUBTRACT)( \\\\+ (CROSS-DOMAIN|INVERT|MERGE|RELOCATE|SCALE SHIFT|SUBTRACT))?$" },
              "result": { "$ref": "#/$defs/text" }
            }
          }
        },
        "innovations": {
          "type": "array",
          "minItems": 3,
          "maxItems": 3,
          "contains": { "required": ["visible"], "properties": { "visible": { "enum": ["exterior", "both"] } } },
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": ["id", "name", "what", "why_new", "plausibility", "visible"],
            "properties": {
              "id": { "type": "string", "pattern": "^N[1-3]$" },
              "name": { "$ref": "#/$defs/text" },
              "what": { "$ref": "#/$defs/text" },
              "why_new": { "$ref": "#/$defs/text" },
              "plausibility": { "$ref": "#/$defs/text" },
              "visible": { "enum": ["exterior", "interior", "both"] }
            }
          }
        },
        "silhouette": { "$ref": "#/$defs/text" },
        "must_avoid": { "type": "array", "minItems": 8, "items": { "$ref": "#/$defs/text" } },
        "hero_moment": { "$ref": "#/$defs/text" },
        "emotion": { "enum": ["awe", "serenity", "power", "mystery", "freedom", "precision"] }
      }
    },
    "self_check": {
      "type": "array",
      "minItems": 10,
      "prefixItems": [
        { "allOf": [{ "$ref": "#/$defs/check" }, { "properties": { "check": { "const": "source_floor" } } }] },
        { "allOf": [{ "$ref": "#/$defs/check" }, { "properties": { "check": { "const": "theme" } } }] },
        { "allOf": [{ "$ref": "#/$defs/check" }, { "properties": { "check": { "const": "departures" } } }] },
        { "allOf": [{ "$ref": "#/$defs/check" }, { "properties": { "check": { "const": "novelty" } } }] },
        { "allOf": [{ "$ref": "#/$defs/check" }, { "properties": { "check": { "const": "plausibility" } } }] },
        { "allOf": [{ "$ref": "#/$defs/check" }, { "properties": { "check": { "const": "coherence" } } }] },
        { "allOf": [{ "$ref": "#/$defs/check" }, { "properties": { "check": { "const": "silhouette" } } }] },
        { "allOf": [{ "$ref": "#/$defs/check" }, { "properties": { "check": { "const": "must_avoid" } } }] },
        { "allOf": [{ "$ref": "#/$defs/check" }, { "properties": { "check": { "const": "hero" } } }] },
        { "allOf": [{ "$ref": "#/$defs/check" }, { "properties": { "check": { "const": "contract_and_names" } } }] }
      ],
      "items": false
    }
  },
  "$defs": {
    "text": { "type": "string", "pattern": "\\\\S" },
    "check": {
      "type": "object",
      "additionalProperties": false,
      "required": ["check", "result", "note"],
      "properties": {
        "check": { "type": "string" },
        "result": { "enum": ["passed", "open"] },
        "note": { "type": "string" }
      },
      "allOf": [
        { "if": { "properties": { "result": { "const": "open" } } }, "then": { "properties": { "note": { "pattern": "\\\\S" } } } }
      ]
    }
  }
}
