    array (
      'id' => 'a31d2de5-4277-49af-bb23-70f26d1d5013',
      'namespace' => 'superyacht',
      'schema_key' => 'Phase3Design',
      'version' => '2.3.0',
      'name' => 'Phase3Design (format phase3-design-v2): the whole Phase 3 answer',
      'schema_content' => '{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://superyacht.local/schemas/Phase3Design",
  "title": "Phase3Design (format phase3-design-v2): the whole Phase 3 answer",
  "x-word-limits": {
    "anchors.yacht": 250,
    "anchors.geometry": 250,
    "anchors.finished_surface": 100,
    "anchors.exterior.*": 250,
    "anchors.interior.*": 250
  },
  "type": "object",
  "required": ["format", "phase", "prompt_version", "project_id", "status", "data", "flags", "notes", "self_check"],
  "additionalProperties": false,
  "properties": {
    "format": {"const": "phase3-design-v2"},
    "phase": {"const": "3"},
    "prompt_version": {"type": "string"},
    "project_id": {"type": "string"},
    "status": {"enum": ["ok", "partial", "fail"], "description": "ok: complete at concept level and every self-check passed; partial: a design with at least one open self-check; fail: no usable design, data is {} and flags names the reasons"},
    "flags": {"type": "array", "items": {"type": "string"}},
    "notes": {"type": "string"},
    "data": {"type": "object"},
    "self_check": {"$ref": "#/$defs/self_check"}
  },
  "allOf": [
    {
      "if": {"required": ["status"], "properties": {"status": {"const": "ok"}}},
      "then": {"properties": {"data": {"$ref": "#/$defs/data"}, "self_check": {"not": {"contains": {"$ref": "#/$defs/open_check"}}}}}
    },
    {
      "if": {"required": ["status"], "properties": {"status": {"const": "partial"}}},
      "then": {"properties": {"data": {"$ref": "#/$defs/data"}, "self_check": {"contains": {"$ref": "#/$defs/open_check"}}}}
    },
    {
      "if": {"required": ["status"], "properties": {"status": {"const": "fail"}}},
      "then": {"properties": {"data": {"type": "object", "maxProperties": 0}, "flags": {"minItems": 1}, "self_check": {"contains": {"$ref": "#/$defs/open_check"}}}}
    }
  ],
  "$defs": {
    "text": {"type": "string", "pattern": "\\\\S"},
    "self_check": {
      "type": "array",
      "minItems": 12,
      "prefixItems": [
        {"allOf": [{"$ref": "#/$defs/check"}, {"properties": {"check": {"const": "dna_fidelity"}}}]},
        {"allOf": [{"$ref": "#/$defs/check"}, {"properties": {"check": {"const": "specs_and_basis"}}}]},
        {"allOf": [{"$ref": "#/$defs/check"}, {"properties": {"check": {"const": "geometry"}}}]},
        {"allOf": [{"$ref": "#/$defs/check"}, {"properties": {"check": {"const": "exterior_and_innovations"}}}]},
        {"allOf": [{"$ref": "#/$defs/check"}, {"properties": {"check": {"const": "interior_design"}}}]},
        {"allOf": [{"$ref": "#/$defs/check"}, {"properties": {"check": {"const": "spatial_connections"}}}]},
        {"allOf": [{"$ref": "#/$defs/check"}, {"properties": {"check": {"const": "operational_limits"}}}]},
        {"allOf": [{"$ref": "#/$defs/check"}, {"properties": {"check": {"const": "build_states"}}}]},
        {"allOf": [{"$ref": "#/$defs/check"}, {"properties": {"check": {"const": "materials_and_lighting"}}}]},
        {"allOf": [{"$ref": "#/$defs/check"}, {"properties": {"check": {"const": "anchors"}}}]},
        {"allOf": [{"$ref": "#/$defs/check"}, {"properties": {"check": {"const": "identity_and_names"}}}]},
        {"allOf": [{"$ref": "#/$defs/check"}, {"properties": {"check": {"const": "contract"}}}]}
      ],
      "items": false
    },
    "check": {
      "type": "object",
      "required": ["check", "result", "note"],
      "additionalProperties": false,
      "properties": {
        "check": {"type": "string"},
        "result": {"enum": ["passed", "open"]},
        "note": {"type": "string"}
      },
      "allOf": [
        {"if": {"properties": {"result": {"const": "open"}}}, "then": {"properties": {"note": {"pattern": "\\\\S"}}}}
      ]
    },
    "open_check": {"type": "object", "required": ["result"], "properties": {"result": {"const": "open"}}},
    "spec": {
      "type": "object",
      "required": ["value", "unit", "basis"],
      "additionalProperties": false,
      "properties": {
        "value": {"type": "number"},
        "unit": {"$ref": "#/$defs/text"},
        "basis": {"enum": ["CONCEPT_ASSUMPTION", "DERIVED", "TRACED"]}
      }
    },
    "spec_metres": {"allOf": [{"$ref": "#/$defs/spec"}, {"properties": {"unit": {"const": "m"}}}]},
    "spec_tonnage": {"allOf": [{"$ref": "#/$defs/spec"}, {"properties": {"unit": {"const": "GT"}}}]},
    "spec_count": {"allOf": [{"$ref": "#/$defs/spec"}, {"properties": {"value": {"type": "integer"}}}]},
    "spec_length": {"allOf": [{"$ref": "#/$defs/spec"}, {"properties": {"value": {"exclusiveMinimum": 0}, "unit": {"const": "m"}}}]},
    "spec_speed": {"allOf": [{"$ref": "#/$defs/spec"}, {"properties": {"value": {"exclusiveMinimum": 0}, "unit": {"const": "kn"}}}]},
    "spec_distance": {"allOf": [{"$ref": "#/$defs/spec"}, {"properties": {"value": {"exclusiveMinimum": 0}, "unit": {"const": "nm"}}}]},
    "exterior": {
      "type": "object",
      "description": "the whole outside of the yacht, one field per part; a part the yacht does not have is described as absent",
      "required": ["silhouette", "bow", "hull", "superstructure", "glazing", "mast_radar", "helidecks", "stern", "water_access"],
      "additionalProperties": false,
      "properties": {
        "silhouette": {"$ref": "#/$defs/text"},
        "bow": {"$ref": "#/$defs/text"},
        "hull": {"$ref": "#/$defs/text"},
        "superstructure": {"$ref": "#/$defs/text"},
        "glazing": {"$ref": "#/$defs/text"},
        "mast_radar": {"$ref": "#/$defs/text"},
        "helidecks": {"$ref": "#/$defs/text"},
        "stern": {"$ref": "#/$defs/text"},
        "water_access": {"$ref": "#/$defs/text"}
      }
    },
    "hex": {"type": "string", "pattern": "^#[0-9A-Fa-f]{6}$"},
    "room_id": {"type": "string", "pattern": "^INT[0-9]{2}$"},
    "zone_id": {"type": "string", "pattern": "^EXT[0-9]{2}$"},
    "data": {
      "type": "object",
      "required": ["yacht_bible", "anchors", "build_states", "canonical"],
      "additionalProperties": false,
      "properties": {
        "yacht_bible": {"$ref": "#/$defs/bible"},
        "anchors": {"$ref": "#/$defs/anchors"},
        "build_states": {
          "type": "object",
          "required": ["BS01", "BS02", "BS03", "BS04", "BS05", "BS06", "BS07", "BS08", "BS09", "BS10", "BS11", "BS12"],
          "additionalProperties": false,
          "patternProperties": {"^BS(0[1-9]|1[0-2])$": {"$ref": "#/$defs/text"}}
        },
        "canonical": {"$ref": "#/$defs/canonicalDesign"}
      }
    },
    "bible": {
      "type": "object",
      "required": ["name", "specs", "fictional_status", "code_assumption", "decks", "colors", "exterior", "innovations", "exterior_zones", "rooms", "lighting_signature", "interior_set_states"],
      "additionalProperties": false,
      "properties": {
        "name": {"$ref": "#/$defs/text"},
        "specs": {
          "type": "object",
          "required": ["loa", "beam", "gross_tonnage", "decks", "guests", "crew", "justifications"],
          "properties": {
            "loa": {"$ref": "#/$defs/spec_metres"},
            "beam": {"$ref": "#/$defs/spec_metres"},
            "gross_tonnage": {"oneOf": [{"type": "null"}, {"$ref": "#/$defs/spec_tonnage"}]},
            "decks": {"$ref": "#/$defs/spec_count"},
            "guests": {"$ref": "#/$defs/spec_count"},
            "crew": {"$ref": "#/$defs/spec_count"},
            "lwl": {"$ref": "#/$defs/spec_length"},
            "draft": {"$ref": "#/$defs/spec_length"},
            "top_speed": {"$ref": "#/$defs/spec_speed"},
            "cruise_speed": {"$ref": "#/$defs/spec_speed"},
            "range_at_cruise": {"$ref": "#/$defs/spec_distance"},
            "justifications": {"type": "object", "additionalProperties": {"$ref": "#/$defs/text"}}
          },
          "additionalProperties": {"$ref": "#/$defs/spec"}
        },
        "exterior": {"$ref": "#/$defs/exterior"},
        "fictional_status": {"$ref": "#/$defs/text"},
        "code_assumption": {"$ref": "#/$defs/text"},
        "decks": {
          "type": "array",
          "minItems": 5,
          "items": {
            "type": "object",
            "required": ["name", "layout"],
            "additionalProperties": false,
            "properties": {"name": {"$ref": "#/$defs/text"}, "layout": {"$ref": "#/$defs/text"}}
          }
        },
        "colors": {
          "type": "array",
          "minItems": 1,
          "maxItems": 3,
          "items": {
            "type": "object",
            "required": ["role", "name", "hex"],
            "additionalProperties": false,
            "properties": {"role": {"$ref": "#/$defs/text"}, "name": {"$ref": "#/$defs/text"}, "hex": {"$ref": "#/$defs/hex"}}
          }
        },
        "innovations": {
          "type": "array",
          "minItems": 3,
          "maxItems": 3,
          "items": {
            "type": "object",
            "required": ["id", "name", "purpose", "position", "geometry", "visible_expression", "effect", "plausibility_note"],
            "additionalProperties": false,
            "properties": {
              "id": {"type": "string", "pattern": "^N[0-9]+$"},
              "name": {"$ref": "#/$defs/text"},
              "purpose": {"$ref": "#/$defs/text", "description": "what the feature does for the people who use the yacht"},
              "position": {"$ref": "#/$defs/text", "description": "where on the yacht the equipment is installed"},
              "geometry": {"$ref": "#/$defs/text"},
              "visible_expression": {"$ref": "#/$defs/text", "description": "what the installed equipment looks like where it is mounted"},
              "effect": {"oneOf": [{"$ref": "#/$defs/text"}, {"type": "null"}], "description": "what is seen where the feature acts without its equipment, or null"},
              "plausibility_note": {"type": "array", "items": {"$ref": "#/$defs/text"}}
            }
          }
        },
        "exterior_zones": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "object",
            "required": ["id", "name", "text", "use"],
            "additionalProperties": false,
            "properties": {
              "id": {"$ref": "#/$defs/zone_id"},
              "name": {"$ref": "#/$defs/text"},
              "text": {"$ref": "#/$defs/text"},
              "use": {"$ref": "#/$defs/text"}
            }
          }
        },
        "rooms": {
          "type": "array",
          "minItems": 10,
          "items": {"$ref": "#/$defs/room"}
        },
        "lighting_signature": {"$ref": "#/$defs/text"},
        "interior_set_states": {
          "type": "object",
          "required": ["bare", "fitout", "finished"],
          "additionalProperties": false,
          "properties": {"bare": {"$ref": "#/$defs/text"}, "fitout": {"$ref": "#/$defs/text"}, "finished": {"$ref": "#/$defs/text"}}
        }
      }
    },
    "room": {
      "type": "object",
      "required": ["id", "name", "position", "size_feel", "use", "activities", "privacy", "layout", "built_ins", "furniture", "surfaces", "palette", "signature_detail", "window_type", "lighting"],
      "additionalProperties": false,
      "properties": {
        "id": {"$ref": "#/$defs/room_id"},
        "name": {"$ref": "#/$defs/text"},
        "position": {"$ref": "#/$defs/text"},
        "size_feel": {"$ref": "#/$defs/text"},
        "use": {"$ref": "#/$defs/text"},
        "activities": {"type": "array", "minItems": 1, "items": {"$ref": "#/$defs/text"}},
        "privacy": {"enum": ["private", "guests", "crew", "mixed"]},
        "layout": {
          "type": "object",
          "required": ["use_zones", "orientation", "circulation", "focal_point"],
          "additionalProperties": false,
          "properties": {
            "use_zones": {"$ref": "#/$defs/text"},
            "orientation": {"$ref": "#/$defs/text"},
            "circulation": {"$ref": "#/$defs/text"},
            "focal_point": {"$ref": "#/$defs/text"}
          }
        },
        "built_ins": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["id", "name", "description"],
            "additionalProperties": false,
            "properties": {
              "id": {"type": "string", "pattern": "^INT[0-9]{2}-B[0-9]{2}$"},
              "name": {"$ref": "#/$defs/text"},
              "description": {"$ref": "#/$defs/text"}
            }
          }
        },
        "furniture": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["item", "placement"],
            "additionalProperties": false,
            "properties": {"item": {"$ref": "#/$defs/text"}, "placement": {"$ref": "#/$defs/text"}}
          }
        },
        "surfaces": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "object",
            "required": ["element", "built_in", "material", "finish"],
            "additionalProperties": false,
            "properties": {
              "element": {"$ref": "#/$defs/text", "description": "the surface or element: floor, walls, ceiling, or a built-in by name"},
              "built_in": {"oneOf": [{"type": "string", "pattern": "^INT[0-9]{2}-B[0-9]{2}$"}, {"type": "null"}]},
              "material": {"$ref": "#/$defs/text"},
              "finish": {"$ref": "#/$defs/text"}
            }
          }
        },
        "palette": {"type": "array", "minItems": 2, "maxItems": 4, "items": {"$ref": "#/$defs/hex"}},
        "signature_detail": {"$ref": "#/$defs/text"},
        "window_type": {"$ref": "#/$defs/text"},
        "lighting": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["source", "position", "serves"],
            "additionalProperties": false,
            "properties": {"source": {"$ref": "#/$defs/text"}, "position": {"$ref": "#/$defs/text"}, "serves": {"$ref": "#/$defs/text"}}
          }
        }
      }
    },
    "anchors": {
      "type": "object",
      "required": ["yacht", "geometry", "finished_surface", "surface_states", "exterior", "interior"],
      "additionalProperties": false,
      "properties": {
        "yacht": {"$ref": "#/$defs/text"},
        "geometry": {"$ref": "#/$defs/text"},
        "finished_surface": {"$ref": "#/$defs/text"},
        "surface_states": {
          "type": "object",
          "required": ["BS06", "BS07", "BS08", "BS09", "BS10", "BS11", "BS12"],
          "additionalProperties": false,
          "patternProperties": {"^BS(0[6-9]|1[0-2])$": {"$ref": "#/$defs/text"}}
        },
        "exterior": {
          "type": "object",
          "additionalProperties": false,
          "patternProperties": {"^EXT[0-9]{2}$": {"$ref": "#/$defs/text"}}
        },
        "interior": {
          "type": "object",
          "additionalProperties": false,
          "patternProperties": {"^INT[0-9]{2}$": {"$ref": "#/$defs/text"}}
        }
      }
    },
    "canonicalDesign": {
      "type": "object",
      "required": ["revision", "revision_kind", "hash", "name", "coordinate_system", "dimensions", "decks", "profile_curve", "plan_outline", "deck_outlines", "landmarks", "surfaces", "build_states", "operational_limits", "spaces", "connections", "routes", "innovations", "identity_features"],
      "additionalProperties": false,
      "properties": {
        "revision": {"type": "integer", "minimum": 0},
        "revision_kind": {"enum": ["draft", "locked"]},
        "hash": {"type": "string", "pattern": "^sha256:[a-f0-9]{64}$", "description": "the answer writes \\"\\"; code compiles the build-state texts and writes this hash before the schema checks the answer"},
        "name": {"type": "string", "minLength": 2, "maxLength": 30},
        "coordinate_system": {
          "type": "object",
          "required": ["x", "y", "z"],
          "additionalProperties": false,
          "description": "the axes every landmark, curve and deck elevation uses",
          "properties": {
            "x": {"const": "fraction of LOA from the bow"},
            "y": {"const": "metres from the centreline, positive to port"},
            "z": {"const": "metres above the design waterline"}
          }
        },
        "dimensions": {
          "type": "object",
          "required": ["loa", "beam", "draft"],
          "description": "every measure of the design, once: the yacht\'s own, and each measure of an innovation\'s equipment under the lowercase id of the innovation and the name of the measure (n1_facet_length) with what it measures in quantity and the unit that quantity takes",
          "properties": {
            "loa": {"$ref": "#/$defs/length_m"},
            "beam": {"$ref": "#/$defs/length_m"},
            "draft": {"$ref": "#/$defs/length_m"}
          },
          "patternProperties": {"^n[0-9]+_": {"$ref": "#/$defs/innovation_measure"}},
          "additionalProperties": {"$ref": "#/$defs/measure"}
        },
        "decks": {
          "type": "array",
          "minItems": 5,
          "items": {
            "type": "object",
            "required": ["name", "floor_z_m", "ceiling_z_m", "height_m", "start_x", "end_x"],
            "properties": {
              "name": {"type": "string", "minLength": 1},
              "floor_z_m": {"type": "number"},
              "ceiling_z_m": {"type": "number"},
              "height_m": {"type": "number", "exclusiveMinimum": 0},
              "setback_m": {"type": "number"},
              "start_x": {"type": "number", "minimum": 0, "maximum": 1},
              "end_x": {"type": "number", "minimum": 0, "maximum": 1}
            }
          }
        },
        "profile_curve": {"$ref": "#/$defs/curve"},
        "plan_outline": {"$ref": "#/$defs/curve"},
        "deck_outlines": {"type": "array", "items": {"type": "object"}},
        "landmarks": {
          "type": "object",
          "additionalProperties": {
            "type": "object",
            "required": ["x", "z"],
            "properties": {
              "x": {"type": "number", "minimum": 0, "maximum": 1},
              "y": {"type": "number"},
              "z": {"type": "number"},
              "above_profile": {"type": "boolean"},
              "above_profile_reason": {"type": "string"}
            }
          }
        },
        "surfaces": {
          "type": "object",
          "required": ["finished", "colors"],
          "properties": {
            "finished": {"type": "string"},
            "colors": {
              "type": "array",
              "maxItems": 3,
              "items": {
                "type": "object",
                "required": ["role", "name", "hex"],
                "properties": {"hex": {"type": "string", "pattern": "^#[0-9A-Fa-f]{6}$"}}
              }
            }
          }
        },
        "build_states": {
          "type": "array",
          "minItems": 8,
          "maxItems": 8,
          "items": {"$ref": "#/$defs/build_state"},
          "description": "exactly BS05-BS12"
        },
        "operational_limits": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["feature", "applies_to", "allowed_when", "otherwise"],
            "properties": {
              "feature": {"type": "string", "minLength": 1},
              "applies_to": {
                "type": "object",
                "required": ["kind", "id"],
                "additionalProperties": false,
                "properties": {
                  "kind": {"enum": ["innovation", "part", "space", "activity"]},
                  "id": {"type": ["string", "null"]}
                },
                "description": "what the limit governs: an innovation id, a BuildState part, a space id, or an activity of the feature itself (id null)"
              },
              "allowed_when": {
                "type": "object",
                "properties": {
                  "max_speed_kn": {"type": "number", "minimum": 0},
                  "at_anchor_only": {"type": "boolean"},
                  "max_sea_state": {"type": "integer", "minimum": 0, "maximum": 9}
                }
              },
              "otherwise": {"type": "string", "minLength": 1},
              "basis": {"type": "string"}
            }
          }
        },
        "spaces": {
          "type": "array",
          "minItems": 10,
          "description": "one entry for every room (INT) and every exterior zone (EXT) of yacht_bible, nothing else",
          "items": {
            "type": "object",
            "required": ["id", "decks", "dimensions"],
            "additionalProperties": false,
            "properties": {
              "id": {"$ref": "#/$defs/space_id"},
              "decks": {"type": "array", "minItems": 1, "uniqueItems": true, "items": {"type": "string", "minLength": 1}, "description": "every deck the space occupies, each once; more than one for a space that rises through decks"},
              "dimensions": {
                "type": "object",
                "required": ["length_m", "width_m", "height_m", "scope"],
                "additionalProperties": false,
                "properties": {
                  "length_m": {"$ref": "#/$defs/space_measure"},
                  "width_m": {"$ref": "#/$defs/space_measure"},
                  "height_m": {"$ref": "#/$defs/space_measure"},
                  "scope": {"type": "string", "minLength": 1, "description": "what the figures measure, e.g. clear interior between finished walls, or the walkable deck area"}
                }
              }
            }
          }
        },
        "connections": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["id", "kind", "between", "users"],
            "additionalProperties": false,
            "properties": {
              "id": {"type": "string", "pattern": "^C[0-9]{2,3}$"},
              "kind": {"enum": ["adjacent", "door", "opening", "stair", "lift", "ramp", "hatch"], "description": "adjacent: the two spaces share a boundary with no passage; every other kind is a passage; a door or opening stays on one level, a passage between decks is a stair, lift, ramp or hatch"},
              "between": {"type": "array", "minItems": 2, "maxItems": 2, "items": {"$ref": "#/$defs/endpoint"}},
              "users": {"type": "array", "uniqueItems": true, "items": {"$ref": "#/$defs/user"}, "description": "who may pass; empty for adjacent"},
              "note": {"type": "string", "description": "where the passage is; required in practice when two passages of the same kind join the same two spaces"}
            }
          }
        },
        "routes": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["id", "purpose", "users", "spaces", "via"],
            "additionalProperties": false,
            "properties": {
              "id": {"type": "string", "pattern": "^R[0-9]{2,3}$"},
              "purpose": {"type": "string", "minLength": 1},
              "users": {"type": "array", "minItems": 1, "uniqueItems": true, "items": {"$ref": "#/$defs/user"}},
              "spaces": {"type": "array", "minItems": 2, "items": {"$ref": "#/$defs/endpoint"}, "description": "the spaces in walking order"},
              "via": {"type": "array", "minItems": 1, "items": {"type": "string", "pattern": "^C[0-9]{2,3}$"}, "description": "the connection between each pair of consecutive spaces"}
            }
          }
        },
        "innovations": {
          "type": "array",
          "minItems": 3,
          "maxItems": 3,
          "items": {
            "type": "object",
            "required": ["id", "mounted_in", "serves", "effect_in", "from_state", "visible_elements"],
            "additionalProperties": false,
            "description": "the measures of the equipment go to canonical.dimensions, its layout and whom each part serves to the innovation\'s geometry text, its structure and risks to its plausibility_note",
            "properties": {
              "id": {"type": "string", "pattern": "^N[0-9]+$"},
              "visible_elements": {"type": "array", "items": {"$ref": "#/$defs/visible_element"}, "description": "every part of the installed equipment that must look the same in every image: each kind of repeated part with how many are seen and how they are arranged, and a single part (count 1) whose size the design states; [] when the equipment has neither"},
              "mounted_in": {"type": "array", "minItems": 1, "uniqueItems": true, "items": {"$ref": "#/$defs/space_id"}, "description": "the spaces where the equipment itself is installed and can be seen"},
              "serves": {"type": "array", "uniqueItems": true, "items": {"$ref": "#/$defs/space_id"}, "description": "the spaces it works for, wherever it is installed"},
              "effect_in": {"type": "array", "uniqueItems": true, "items": {"$ref": "#/$defs/space_id"}, "description": "the spaces where its visible effect appears without the equipment"},
              "from_state": {"oneOf": [{"$ref": "#/$defs/state"}, {"type": "null"}], "description": "the first build state in which it physically exists"}
            }
          }
        },
        "identity_features": {
          "type": "array",
          "minItems": 1,
          "description": "what an image of the yacht or of one of its spaces keeps recognisable or must never show; rules a camera cannot see belong elsewhere",
          "items": {
            "type": "object",
            "required": ["id", "kind", "scope", "description", "from_state"],
            "additionalProperties": false,
            "properties": {
              "id": {"type": "string", "pattern": "^[A-Z0-9][A-Z0-9-]{1,40}$"},
              "kind": {"enum": ["must_keep", "must_not"]},
              "scope": {"type": "array", "minItems": 1, "uniqueItems": true, "items": {"anyOf": [{"const": "YACHT"}, {"$ref": "#/$defs/space_id"}]}},
              "description": {"type": "string", "minLength": 1, "maxLength": 240, "description": "a noun phrase naming the visible feature (must_keep) or the visible thing that must not appear (must_not), never opening with do not, no or not; the system writes Must keep: or Avoid: before it"},
              "from_state": {"oneOf": [{"$ref": "#/$defs/state"}, {"type": "null"}]}
            }
          }
        }
      },
      "allOf": [
        {
          "if": {"properties": {"revision_kind": {"const": "locked"}}},
          "then": {"properties": {"revision": {"minimum": 1}}}
        }
      ]
    },
    "measure": {
      "type": "object",
      "required": ["value", "unit", "basis"],
      "properties": {
        "value": {"type": "number"},
        "unit": {"type": "string"},
        "basis": {"enum": ["CONCEPT_ASSUMPTION", "DERIVED", "TRACED"]}
      }
    },
    "length_m": {
      "type": "object",
      "required": ["value", "unit", "basis"],
      "properties": {
        "value": {"type": "number", "exclusiveMinimum": 0},
        "unit": {"const": "m"},
        "basis": {"enum": ["CONCEPT_ASSUMPTION", "DERIVED", "TRACED"]}
      }
    },
    "space_measure": {
      "type": "object",
      "required": ["value", "basis"],
      "additionalProperties": false,
      "properties": {
        "value": {"oneOf": [{"type": "number", "exclusiveMinimum": 0}, {"type": "null"}]},
        "basis": {"enum": ["CONCEPT_ASSUMPTION", "DERIVED", "UNKNOWN"]}
      },
      "if": {"properties": {"value": {"type": "null"}}},
      "then": {"properties": {"basis": {"const": "UNKNOWN"}}},
      "else": {"properties": {"basis": {"enum": ["CONCEPT_ASSUMPTION", "DERIVED"]}}}
    },
    "curve": {
      "type": "array",
      "minItems": 20,
      "items": {"type": "array", "minItems": 2, "maxItems": 2, "items": {"type": "number"}}
    },
    "innovation_measure": {
      "type": "object",
      "required": ["value", "unit", "basis", "quantity"],
      "additionalProperties": false,
      "description": "one measure of an innovation\'s equipment; quantity says what it measures and fixes its unit",
      "properties": {
        "value": {"type": "number", "exclusiveMinimum": 0},
        "unit": {"enum": ["m", "m3", "t"]},
        "basis": {"enum": ["CONCEPT_ASSUMPTION", "DERIVED", "TRACED"]},
        "quantity": {"enum": ["length", "volume", "mass"], "description": "length in m, volume in m3, mass in t; only a length sizes a part in an image"}
      },
      "oneOf": [
        {"properties": {"quantity": {"const": "length"}, "unit": {"const": "m"}}},
        {"properties": {"quantity": {"const": "volume"}, "unit": {"const": "m3"}}},
        {"properties": {"quantity": {"const": "mass"}, "unit": {"const": "t"}}}
      ]
    },
    "visible_element": {
      "type": "object",
      "required": ["element", "count", "arrangement", "basis", "measures"],
      "additionalProperties": false,
      "properties": {
        "element": {"type": "string", "minLength": 1, "description": "the part as a camera sees it, e.g. mirror facet"},
        "count": {"type": "integer", "minimum": 1, "description": "how many of them are seen on the finished yacht"},
        "arrangement": {"type": "string", "minLength": 1, "description": "how they are laid out, e.g. two rows of six along the crest"},
        "basis": {"enum": ["CONCEPT_ASSUMPTION", "DERIVED"], "description": "CONCEPT_ASSUMPTION when engineering has not fixed the number"},
        "measures": {"type": "array", "uniqueItems": true, "items": {"type": "string", "pattern": "^n[0-9]+_[a-z0-9]+(_[a-z0-9]+)*$"}, "description": "the keys of the canonical.dimensions of this innovation whose quantity is length, that size this part as a camera sees it; [] when the design gives none. Only these measures are written into an image prompt"}
      }
    },
    "space_id": {"type": "string", "pattern": "^(INT|EXT)[0-9]{2}$"},
    "endpoint": {"anyOf": [{"$ref": "#/$defs/space_id"}, {"const": "SEA"}]},
    "user": {"enum": ["owner", "guests", "crew"]},
    "state": {"type": "string", "pattern": "^BS(0[5-9]|1[0-2])$"},
    "part": {"enum": ["keel_blocks", "hull_shell", "main_deck", "superstructure", "glazing", "hull_doors", "observation_blister", "helideck", "mast", "stern_platform", "terraces", "scaffolding_on_hull"]},
    "build_state": {
      "type": "object",
      "required": ["id", "kind", "present_parts", "absent_parts", "surfaces_by_part", "compiled_text"],
      "properties": {
        "id": {"$ref": "#/$defs/state"},
        "kind": {"enum": ["scale_model", "build", "finished"]},
        "present_parts": {"type": "array", "uniqueItems": true, "items": {"$ref": "#/$defs/part"}},
        "absent_parts": {"type": "array", "uniqueItems": true, "items": {"$ref": "#/$defs/part"}},
        "surfaces_by_part": {
          "type": "object",
          "propertyNames": {"$ref": "#/$defs/part"},
          "additionalProperties": {"enum": ["scale_model_white", "bare_steel", "steel_primer", "raw_aluminium", "protective_film", "filler_primer", "final_paint", "final_glass", "teak", "other_final"]}
        },
        "compiled_text": {"type": "string", "description": "STATE GEOMETRY + SURFACE STATE written by code"}
      }
    }
  }
}
