      'schema_sha256' => '47c4c4f3bc26d9c2529fe00b8a8510d3110893fe90f98c8b4cbe96aa05ad9aee',
      'source_file' => 'release:phase-3-design-v6/Phase3Design.schema.json',
      'json_schema_id' => 'https://superyacht.local/schemas/Phase3Design',
