      'schema_sha256' => '128cab9443c246e3b13a6933246431a5837782cc752296b5941bfc0ff054cb72',
      'source_file' => 'release:phase-3-design-v7/Phase3Design.schema.json',
      'json_schema_id' => 'https://superyacht.local/schemas/Phase3Design',
      'json_schema_dialect' => 'https://json-schema.org/draft/2020-12/schema',
      'dependencies' => '[]',
      'status' => 'published',
      'change_note' => 'Release phase-3-design-v7 (plan sha256:98a0cf91a6db69a3fa412fdf0ff7b356e39c8092e506a21edb5b604f1fd0724b).',
      'created_by' => 'video:phase-release',
