      'schema_sha256' => '82185591b0d687591a1bea3fe8965bfbc3097d03067ddb85f18a7e63ad5534b3',
      'source_file' => 'release:phase-3-design-v8/Phase3Design.schema.json',
      'json_schema_id' => 'https://superyacht.local/schemas/Phase3Design',
