    31 => 
    array (
      'id' => 'a31ec493-2e4c-4098-b6e4-3d49e55e985e',
      'namespace' => 'superyacht',
      'schema_key' => 'Phase3Design',
      'version' => '3.2.0',
      'name' => 'Phase3Design 3.2.0 (format phase3-design-v3): one object-based yacht design record with its model sheet, from studio to launch, its prose sized to its object',
      'schema_content' => '{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://superyacht.local/schemas/Phase3Design",
  "title": "Phase3Design 3.2.0 (format phase3-design-v3): one object-based yacht design record with its model sheet, from studio to launch, its prose sized to its object",
  "type": "object",
  "required": ["format", "phase", "prompt_version", "project_id", "status", "data", "flags"],
  "additionalProperties": false,
  "properties": {
    "format": {"const": "phase3-design-v3"},
    "phase": {"const": "3"},
    "prompt_version": {"$ref": "#/$defs/text"},
    "project_id": {"$ref": "#/$defs/text"},
    "status": {"enum": ["ok", "partial", "fail"], "description": "ok: no blocking source issue; partial: a design with at least one blocking source issue; fail: no usable design, data is {} and flags names the reasons"},
    "data": {"type": "object"},
    "flags": {"type": "array", "items": {"$ref": "#/$defs/text"}}
  },
  "allOf": [
    {
      "if": {"required": ["status"], "properties": {"status": {"const": "ok"}}},
      "then": {"properties": {"data": {"allOf": [{"$ref": "#/$defs/data"}, {"properties": {"source_issues": {"not": {"contains": {"$ref": "#/$defs/blocking_issue"}}}}}]}}}
    },
    {
      "if": {"required": ["status"], "properties": {"status": {"const": "partial"}}},
      "then": {"properties": {"data": {"allOf": [{"$ref": "#/$defs/data"}, {"properties": {"source_issues": {"contains": {"$ref": "#/$defs/blocking_issue"}}}}]}}}
    },
    {
      "if": {"required": ["status"], "properties": {"status": {"const": "fail"}}},
      "then": {"properties": {"data": {"type": "object", "maxProperties": 0}, "flags": {"minItems": 1}}}
    }
  ],
  "$defs": {
    "text": {"type": "string", "pattern": "\\\\S"},
    "text_or_null": {"oneOf": [{"$ref": "#/$defs/text"}, {"type": "null"}]},
    "hex": {"type": "string", "pattern": "^#[0-9A-Fa-f]{6}$"},
    "basis": {"enum": ["CONCEPT_ASSUMPTION", "DERIVED", "TRACED"]},
    "count_basis": {"enum": ["CONCEPT_ASSUMPTION", "DERIVED"]},
    "snake": {"type": "string", "pattern": "^[a-z][a-z0-9_]*$"},

    "part_id": {"type": "string", "pattern": "^P[0-9]{2,3}$"},
    "configuration_id": {"type": "string", "pattern": "^P[0-9]{2,3}-K[0-9]{2}$"},
    "light_id": {"type": "string", "pattern": "^(P[0-9]{2,3}|(INT|EXT)[0-9]{2}(-S[0-9]{2})?)-L[0-9]{2}$"},
    "space_id": {"type": "string", "pattern": "^(INT|EXT)[0-9]{2}$"},
    "exterior_space_id": {"type": "string", "pattern": "^EXT[0-9]{2}$"},
    "zone_id": {"type": "string", "pattern": "^(INT|EXT)[0-9]{2}(-S[0-9]{2})?-Z[0-9]{2}$"},
    "subspace_id": {"type": "string", "pattern": "^(INT|EXT)[0-9]{2}-S[0-9]{2}$"},
    "instance_id": {"type": "string", "pattern": "^(INT|EXT)[0-9]{2}-S[0-9]{2}-[0-9]{1,2}$"},
    "built_in_id": {"type": "string", "pattern": "^(INT|EXT)[0-9]{2}(-S[0-9]{2})?-B[0-9]{2}$"},
    "connection_id": {"type": "string", "pattern": "^C[0-9]{2,3}$"},
    "innovation_id": {"type": "string", "pattern": "^N[0-9]+$"},
    "mode_id": {"type": "string", "pattern": "^N[0-9]+-M[0-9]{2}$"},
    "limit_id": {"type": "string", "pattern": "^L[0-9]{2,3}$"},
    "moment_id": {"type": "string", "pattern": "^M[0-9]+$"},
    "color_id": {"type": "string", "pattern": "^C[1-3]$"},
    "issue_id": {"type": "string", "pattern": "^SI[0-9]{2,3}$"},
    "rule_id": {"type": "string", "pattern": "^[A-Z0-9]+-[A-Z0-9-]{1,40}$"},
    "state": {"type": "string", "pattern": "^BS(0[1-9]|1[0-2])$"},
    "physical_state": {"type": "string", "pattern": "^BS(0[6-9]|1[0-2])$"},
    "place_id": {"anyOf": [{"$ref": "#/$defs/space_id"}, {"$ref": "#/$defs/zone_id"}, {"$ref": "#/$defs/subspace_id"}, {"$ref": "#/$defs/instance_id"}]},
    "endpoint": {"anyOf": [{"$ref": "#/$defs/place_id"}, {"const": "SEA"}, {"const": "OUTSIDE"}]},
    "design_ref": {"anyOf": [{"$ref": "#/$defs/part_id"}, {"$ref": "#/$defs/place_id"}, {"$ref": "#/$defs/innovation_id"}, {"$ref": "#/$defs/connection_id"}, {"$ref": "#/$defs/rule_id"}]},
    "view_ref": {"anyOf": [{"$ref": "#/$defs/part_id"}, {"$ref": "#/$defs/connection_id"}, {"$ref": "#/$defs/innovation_id"}, {"$ref": "#/$defs/exterior_space_id"}, {"$ref": "#/$defs/zone_id"}]},
    "user": {"enum": ["owner", "guests", "crew"]},
    "facing": {"enum": ["port", "starboard", "both_sides", "forward", "aft", "up", "down"]},
    "light_state": {"anyOf": [{"enum": ["fitout", "finished"]}, {"$ref": "#/$defs/physical_state"}]},

    "spec": {
      "type": "object", "required": ["value", "unit", "basis"], "additionalProperties": false,
      "properties": {"value": {"type": "number"}, "unit": {"$ref": "#/$defs/text"}, "basis": {"$ref": "#/$defs/basis"}}
    },
    "spec_metres": {"allOf": [{"$ref": "#/$defs/spec"}, {"properties": {"value": {"exclusiveMinimum": 0}, "unit": {"const": "m"}}}]},
    "spec_tonnage": {"allOf": [{"$ref": "#/$defs/spec"}, {"properties": {"value": {"exclusiveMinimum": 0}, "unit": {"const": "GT"}}}]},
    "spec_count": {"allOf": [{"$ref": "#/$defs/spec"}, {"properties": {"value": {"type": "integer", "minimum": 1}, "unit": {"const": "persons"}}}]},
    "spec_speed": {"allOf": [{"$ref": "#/$defs/spec"}, {"properties": {"value": {"exclusiveMinimum": 0}, "unit": {"const": "kn"}}}]},
    "spec_distance": {"allOf": [{"$ref": "#/$defs/spec"}, {"properties": {"value": {"exclusiveMinimum": 0}, "unit": {"const": "nm"}}}]},
    "measure": {
      "type": "object", "required": ["value", "basis"], "additionalProperties": false,
      "properties": {"value": {"oneOf": [{"type": "number", "exclusiveMinimum": 0}, {"type": "null"}]}, "basis": {"enum": ["CONCEPT_ASSUMPTION", "DERIVED", "UNKNOWN"]}},
      "if": {"properties": {"value": {"type": "null"}}},
      "then": {"properties": {"basis": {"const": "UNKNOWN"}}},
      "else": {"properties": {"basis": {"enum": ["CONCEPT_ASSUMPTION", "DERIVED"]}}}
    },
    "innovation_measure": {
      "type": "object", "required": ["value", "unit", "basis", "quantity"], "additionalProperties": false,
      "properties": {
        "value": {"type": "number", "exclusiveMinimum": 0},
        "unit": {"enum": ["m", "m3", "t"]},
        "basis": {"$ref": "#/$defs/basis"},
        "quantity": {"enum": ["length", "volume", "mass"]}
      },
      "oneOf": [
        {"properties": {"quantity": {"const": "length"}, "unit": {"const": "m"}}},
        {"properties": {"quantity": {"const": "volume"}, "unit": {"const": "m3"}}},
        {"properties": {"quantity": {"const": "mass"}, "unit": {"const": "t"}}}
      ]
    },

    "curve": {
      "type": "array", "minItems": 20,
      "items": {"type": "array", "prefixItems": [{"type": "number", "minimum": 0, "maximum": 1}, {"type": "number"}], "minItems": 2, "maxItems": 2}
    },
    "box": {
      "type": "object", "required": ["x_from", "x_to", "y_min", "y_max", "z_min", "z_max"], "additionalProperties": false,
      "properties": {
        "x_from": {"type": "number", "minimum": 0, "maximum": 1}, "x_to": {"type": "number", "minimum": 0, "maximum": 1},
        "y_min": {"type": "number"}, "y_max": {"type": "number"}, "z_min": {"type": "number"}, "z_max": {"type": "number"}
      }
    },
    "plan_box": {
      "type": "object", "required": ["x_from", "x_to", "y_min", "y_max"], "additionalProperties": false,
      "properties": {
        "x_from": {"type": "number", "minimum": 0, "maximum": 1}, "x_to": {"type": "number", "minimum": 0, "maximum": 1},
        "y_min": {"type": "number"}, "y_max": {"type": "number"}
      }
    },
    "point": {
      "type": "object", "required": ["x", "z"], "additionalProperties": false,
      "properties": {
        "x": {"type": "number", "minimum": 0, "maximum": 1}, "y": {"type": "number"}, "z": {"type": "number"},
        "above_profile": {"type": "boolean"}, "above_profile_reason": {"$ref": "#/$defs/text"}
      },
      "if": {"required": ["above_profile"], "properties": {"above_profile": {"const": true}}},
      "then": {"required": ["above_profile_reason"]}
    },
    "points": {"type": "object", "propertyNames": {"pattern": "^[a-z][a-z0-9_]*$"}, "additionalProperties": {"$ref": "#/$defs/point"}},

    "configuration": {
      "type": "object", "required": ["id", "name", "description", "default"], "additionalProperties": false,
      "properties": {"id": {"$ref": "#/$defs/configuration_id"}, "name": {"$ref": "#/$defs/text"}, "description": {"$ref": "#/$defs/text"}, "default": {"type": "boolean"}}
    },
    "configurations": {
      "type": "array", "items": {"$ref": "#/$defs/configuration"},
      "if": {"minItems": 1},
      "then": {"contains": {"required": ["default"], "properties": {"default": {"const": true}}}, "minContains": 1, "maxContains": 1}
    },
    "light_source": {
      "type": "object", "required": ["id", "source", "zone", "position", "serves", "installed", "operable"], "additionalProperties": false,
      "properties": {
        "id": {"$ref": "#/$defs/light_id"},
        "source": {"$ref": "#/$defs/text"},
        "zone": {"oneOf": [{"$ref": "#/$defs/zone_id"}, {"type": "null"}]},
        "position": {"$ref": "#/$defs/text"},
        "serves": {"$ref": "#/$defs/text"},
        "installed": {"$ref": "#/$defs/light_state"},
        "operable": {"$ref": "#/$defs/light_state"}
      }
    },
    "room_light": {"allOf": [{"$ref": "#/$defs/light_source"}, {"properties": {"installed": {"enum": ["fitout", "finished"]}, "operable": {"enum": ["fitout", "finished"]}}}]},
    "exterior_light": {"allOf": [{"$ref": "#/$defs/light_source"}, {"properties": {"installed": {"$ref": "#/$defs/physical_state"}, "operable": {"$ref": "#/$defs/physical_state"}}}]},
    "part_light": {"allOf": [{"$ref": "#/$defs/exterior_light"}, {"properties": {"zone": {"type": "null"}}}]},

    "data": {
      "type": "object",
      "required": ["vessel", "parts", "decks", "spaces", "connections", "routes", "innovations", "operational_limits", "build_states", "identity_rules", "source_issues", "model_sheet"],
      "additionalProperties": false,
      "properties": {
        "vessel": {"$ref": "#/$defs/vessel"},
        "parts": {"$ref": "#/$defs/parts"},
        "decks": {"type": "array", "minItems": 5, "items": {"$ref": "#/$defs/deck"}},
        "spaces": {"$ref": "#/$defs/spaces"},
        "connections": {"type": "array", "minItems": 1, "items": {"$ref": "#/$defs/connection"}},
        "routes": {"type": "array", "minItems": 1, "items": {"$ref": "#/$defs/route"}},
        "innovations": {"type": "array", "minItems": 3, "maxItems": 3, "items": {"$ref": "#/$defs/innovation"}},
        "operational_limits": {"type": "array", "items": {"$ref": "#/$defs/limit"}},
        "build_states": {"$ref": "#/$defs/build_states"},
        "identity_rules": {"type": "array", "minItems": 1, "items": {"$ref": "#/$defs/identity_rule"}},
        "source_issues": {"type": "array", "items": {"$ref": "#/$defs/source_issue"}},
        "model_sheet": {"$ref": "#/$defs/model_sheet"}
      }
    },

    "vessel": {
      "type": "object",
      "required": ["name", "concept", "departures", "signature_moments", "fictional_status", "code_assumption", "propulsion", "specs", "coordinate_system", "profile_curve", "plan_outline", "symmetry", "silhouette", "glazing", "palette", "exterior_materials", "lighting_signature", "interior_set_states", "engineering_notes"],
      "additionalProperties": false,
      "properties": {
        "name": {"type": "string", "minLength": 2, "maxLength": 30, "pattern": "\\\\S"},
        "concept": {"$ref": "#/$defs/text"},
        "departures": {
          "type": "array", "minItems": 1,
          "items": {
            "type": "object", "required": ["departure", "refs", "note"], "additionalProperties": false,
            "properties": {"departure": {"$ref": "#/$defs/text"}, "refs": {"type": "array", "minItems": 1, "items": {"$ref": "#/$defs/design_ref"}}, "note": {"$ref": "#/$defs/text"}}
          }
        },
        "signature_moments": {
          "type": "array", "minItems": 2, "maxItems": 5,
          "items": {
            "type": "object", "required": ["id", "hero", "description", "spaces", "parts", "configurations", "limits", "time_light"], "additionalProperties": false,
            "properties": {
              "id": {"$ref": "#/$defs/moment_id"},
              "hero": {"type": "boolean"},
              "description": {"$ref": "#/$defs/text"},
              "spaces": {"type": "array", "minItems": 1, "items": {"$ref": "#/$defs/place_id"}},
              "parts": {"type": "array", "items": {"$ref": "#/$defs/part_id"}},
              "configurations": {"type": "array", "items": {"$ref": "#/$defs/configuration_id"}},
              "limits": {"type": "array", "items": {"$ref": "#/$defs/limit_id"}},
              "time_light": {"$ref": "#/$defs/text_or_null"}
            }
          },
          "contains": {"required": ["hero"], "properties": {"hero": {"const": true}}}, "minContains": 1, "maxContains": 1
        },
        "fictional_status": {"const": "CONCEPT SPECS — NOT A REAL VESSEL"},
        "code_assumption": {"$ref": "#/$defs/text"},
        "propulsion": {"$ref": "#/$defs/text"},
        "specs": {
          "type": "object",
          "required": ["loa", "beam", "draft", "gross_tonnage", "guests", "crew", "justifications"],
          "additionalProperties": false,
          "properties": {
            "loa": {"allOf": [{"$ref": "#/$defs/spec_metres"}, {"properties": {"value": {"minimum": 110, "maximum": 180}}}]},
            "beam": {"$ref": "#/$defs/spec_metres"},
            "draft": {"$ref": "#/$defs/spec_metres"},
            "lwl": {"$ref": "#/$defs/spec_metres"},
            "gross_tonnage": {"oneOf": [{"type": "null"}, {"$ref": "#/$defs/spec_tonnage"}]},
            "guests": {"$ref": "#/$defs/spec_count"},
            "crew": {"$ref": "#/$defs/spec_count"},
            "top_speed": {"$ref": "#/$defs/spec_speed"},
            "cruise_speed": {"$ref": "#/$defs/spec_speed"},
            "range_at_cruise": {"$ref": "#/$defs/spec_distance"},
            "justifications": {"type": "object", "propertyNames": {"enum": ["loa", "beam", "draft", "lwl", "gross_tonnage", "guests", "crew", "top_speed", "cruise_speed", "range_at_cruise"]}, "additionalProperties": {"$ref": "#/$defs/text"}}
          }
        },
        "coordinate_system": {
          "type": "object", "required": ["x", "y", "z"], "additionalProperties": false,
          "properties": {
            "x": {"const": "fraction of LOA from the bow"},
            "y": {"const": "metres from the centreline, positive to port"},
            "z": {"const": "metres above the design waterline"}
          }
        },
        "profile_curve": {"$ref": "#/$defs/curve"},
        "plan_outline": {"$ref": "#/$defs/curve"},
        "symmetry": {"$ref": "#/$defs/text"},
        "silhouette": {"$ref": "#/$defs/text"},
        "glazing": {"$ref": "#/$defs/text"},
        "palette": {
          "type": "array", "minItems": 1, "maxItems": 3,
          "allOf": [
            {"contains": {"required": ["role"], "properties": {"role": {"const": "hull"}}}, "minContains": 0, "maxContains": 1},
            {"contains": {"required": ["role"], "properties": {"role": {"const": "superstructure"}}}, "minContains": 0, "maxContains": 1},
            {"contains": {"required": ["role"], "properties": {"role": {"const": "accent"}}}, "minContains": 0, "maxContains": 1}
          ],
          "items": {
            "type": "object", "required": ["id", "role", "name", "hex", "finish", "applied_to"], "additionalProperties": false,
            "properties": {
              "id": {"$ref": "#/$defs/color_id"},
              "role": {"enum": ["hull", "superstructure", "accent"]},
              "name": {"$ref": "#/$defs/text"},
              "hex": {"$ref": "#/$defs/hex"},
              "finish": {"$ref": "#/$defs/text"},
              "applied_to": {"$ref": "#/$defs/text"}
            }
          }
        },
        "exterior_materials": {
          "type": "array", "minItems": 3,
          "items": {
            "type": "object", "required": ["element", "material", "finish"], "additionalProperties": false,
            "properties": {"element": {"$ref": "#/$defs/text"}, "material": {"$ref": "#/$defs/text"}, "finish": {"$ref": "#/$defs/text"}}
          }
        },
        "lighting_signature": {
          "type": "object", "required": ["text", "sources"], "additionalProperties": false,
          "properties": {"text": {"$ref": "#/$defs/text"}, "sources": {"type": "array", "minItems": 1, "uniqueItems": true, "items": {"$ref": "#/$defs/light_id"}}}
        },
        "interior_set_states": {
          "type": "object", "required": ["bare", "fitout", "finished"], "additionalProperties": false,
          "properties": {"bare": {"$ref": "#/$defs/text"}, "fitout": {"$ref": "#/$defs/text"}, "finished": {"$ref": "#/$defs/text"}}
        },
        "engineering_notes": {"type": "array", "items": {"$ref": "#/$defs/text"}}
      }
    },

    "parts": {
      "type": "array", "minItems": 12,
      "items": {"$ref": "#/$defs/part"},
      "allOf": [
        {"contains": {"required": ["kind", "present"], "properties": {"kind": {"const": "bow"}, "present": {"const": true}}}},
        {"contains": {"required": ["kind", "present"], "properties": {"kind": {"const": "hull"}, "present": {"const": true}}}},
        {"contains": {"required": ["kind", "present"], "properties": {"kind": {"const": "superstructure"}, "present": {"const": true}}}},
        {"contains": {"required": ["kind", "present"], "properties": {"kind": {"const": "stern"}, "present": {"const": true}}}},
        {"contains": {"required": ["kind", "present"], "properties": {"kind": {"const": "water_access"}, "present": {"const": true}}}},
        {"contains": {"required": ["kind", "present"], "properties": {"kind": {"const": "ground_tackle"}, "present": {"const": true}}}},
        {"contains": {"required": ["kind"], "properties": {"kind": {"const": "mast_radar"}}}},
        {"contains": {"required": ["kind"], "properties": {"kind": {"const": "helideck"}}}},
        {"contains": {"required": ["kind"], "properties": {"kind": {"const": "propulsor"}}}},
        {"contains": {"required": ["kind"], "properties": {"kind": {"const": "rudder"}}}},
        {"contains": {"required": ["kind"], "properties": {"kind": {"const": "stabiliser"}}}},
        {"contains": {"required": ["kind"], "properties": {"kind": {"const": "thruster"}}}}
      ]
    },
    "part": {
      "type": "object",
      "required": ["id", "kind", "name", "parent", "inside", "present", "description", "extent", "faces", "surfaces", "relations", "elements", "configurations", "lighting", "from_state", "until_state", "points"],
      "additionalProperties": false,
      "properties": {
        "id": {"$ref": "#/$defs/part_id"},
        "kind": {"enum": ["bow", "hull", "superstructure", "mast_radar", "helideck", "stern", "water_access", "ground_tackle", "propulsor", "rudder", "stabiliser", "thruster", "tender", "closure", "equipment"]},
        "name": {"$ref": "#/$defs/text"},
        "parent": {"oneOf": [{"$ref": "#/$defs/part_id"}, {"type": "null"}]},
        "inside": {"oneOf": [{"$ref": "#/$defs/space_id"}, {"type": "null"}]},
        "present": {"type": "boolean"},
        "description": {"$ref": "#/$defs/text"},
        "extent": {"oneOf": [{"$ref": "#/$defs/box"}, {"type": "null"}]},
        "faces": {
          "type": "array",
          "items": {
            "type": "object", "required": ["facing", "description"], "additionalProperties": false,
            "properties": {"facing": {"$ref": "#/$defs/facing"}, "description": {"$ref": "#/$defs/text"}}
          }
        },
        "surfaces": {
          "type": "array",
          "items": {
            "type": "object", "required": ["element", "color_id", "material", "finish"], "additionalProperties": false,
            "properties": {
              "element": {"$ref": "#/$defs/text"},
              "color_id": {"oneOf": [{"$ref": "#/$defs/color_id"}, {"type": "null"}]},
              "material": {"$ref": "#/$defs/text"},
              "finish": {"$ref": "#/$defs/text"}
            }
          }
        },
        "relations": {
          "type": "array",
          "items": {
            "type": "object", "required": ["type", "target", "note"], "additionalProperties": false,
            "properties": {"type": {"enum": ["rests_on", "adjoins", "contains", "overhangs", "covers"]}, "target": {"$ref": "#/$defs/part_id"}, "note": {"$ref": "#/$defs/text"}}
          }
        },
        "elements": {
          "type": "array",
          "items": {
            "type": "object", "required": ["element", "count", "arrangement", "size"], "additionalProperties": false,
            "properties": {"element": {"$ref": "#/$defs/text"}, "count": {"type": "integer", "minimum": 1}, "arrangement": {"$ref": "#/$defs/text"}, "size": {"$ref": "#/$defs/text_or_null"}}
          }
        },
        "configurations": {"$ref": "#/$defs/configurations"},
        "lighting": {"type": "array", "items": {"$ref": "#/$defs/part_light"}},
        "from_state": {"oneOf": [{"$ref": "#/$defs/physical_state"}, {"type": "null"}]},
        "until_state": {"oneOf": [{"$ref": "#/$defs/physical_state"}, {"type": "null"}]},
        "points": {"$ref": "#/$defs/points"}
      },
      "if": {"required": ["present"], "properties": {"present": {"const": false}}},
      "then": {"properties": {"extent": {"type": "null"}, "from_state": {"type": "null"}, "until_state": {"type": "null"}, "configurations": {"maxItems": 0}, "lighting": {"maxItems": 0}}},
      "else": {"properties": {"extent": {"$ref": "#/$defs/box"}, "from_state": {"$ref": "#/$defs/physical_state"}}}
    },

    "deck": {
      "type": "object", "required": ["name", "floor_z_m", "ceiling_z_m", "segments", "layout"], "additionalProperties": false,
      "properties": {
        "name": {"$ref": "#/$defs/text"},
        "floor_z_m": {"type": "number"},
        "ceiling_z_m": {"type": "number"},
        "setback_m": {"type": "number", "minimum": 0},
        "segments": {
          "type": "array",
          "items": {
            "type": "object", "required": ["x_from", "x_to"], "additionalProperties": false,
            "properties": {"x_from": {"type": "number", "minimum": 0, "maximum": 1}, "x_to": {"type": "number", "minimum": 0, "maximum": 1}}
          }
        },
        "layout": {
          "type": "object", "required": ["fore", "mid", "aft"], "additionalProperties": false,
          "properties": {"fore": {"$ref": "#/$defs/text"}, "mid": {"$ref": "#/$defs/text"}, "aft": {"$ref": "#/$defs/text"}}
        }
      }
    },

    "dimensions": {
      "type": "object", "required": ["length_m", "width_m", "height_m", "scope"], "additionalProperties": false,
      "properties": {"length_m": {"$ref": "#/$defs/measure"}, "width_m": {"$ref": "#/$defs/measure"}, "height_m": {"$ref": "#/$defs/measure"}, "scope": {"$ref": "#/$defs/text"}}
    },
    "zone": {
      "type": "object", "required": ["id", "name", "side", "use"], "additionalProperties": false,
      "properties": {
        "id": {"$ref": "#/$defs/zone_id"},
        "name": {"$ref": "#/$defs/text"},
        "side": {"enum": ["forward", "aft", "port", "starboard", "inboard", "outboard", "centre"]},
        "use": {"$ref": "#/$defs/text"}
      }
    },
    "layout": {
      "type": "object", "required": ["orientation", "circulation", "focal_point"], "additionalProperties": false,
      "properties": {"orientation": {"$ref": "#/$defs/text"}, "circulation": {"$ref": "#/$defs/text"}, "focal_point": {"$ref": "#/$defs/text"}}
    },
    "built_in": {
      "type": "object", "required": ["id", "name", "zone", "description"], "additionalProperties": false,
      "properties": {"id": {"$ref": "#/$defs/built_in_id"}, "name": {"$ref": "#/$defs/text"}, "zone": {"oneOf": [{"$ref": "#/$defs/zone_id"}, {"type": "null"}]}, "description": {"$ref": "#/$defs/text"}}
    },
    "furniture": {
      "type": "object", "required": ["item", "zone", "placement"], "additionalProperties": false,
      "properties": {"item": {"$ref": "#/$defs/text"}, "zone": {"oneOf": [{"$ref": "#/$defs/zone_id"}, {"type": "null"}]}, "placement": {"$ref": "#/$defs/text"}}
    },
    "space_surface": {
      "type": "object", "required": ["element", "built_in", "color_id", "material", "finish"], "additionalProperties": false,
      "properties": {
        "element": {"$ref": "#/$defs/text"},
        "built_in": {"oneOf": [{"$ref": "#/$defs/built_in_id"}, {"type": "null"}]},
        "color_id": {"oneOf": [{"$ref": "#/$defs/color_id"}, {"type": "null"}]},
        "material": {"$ref": "#/$defs/text"},
        "finish": {"$ref": "#/$defs/text"}
      }
    },
    "instance": {
      "type": "object", "required": ["id", "position", "differences"], "additionalProperties": false,
      "properties": {"id": {"$ref": "#/$defs/instance_id"}, "position": {"$ref": "#/$defs/plan_box"}, "differences": {"type": "string"}}
    },
    "subspace": {
      "type": "object",
      "required": ["id", "name", "count", "arrangement", "dimensions", "zones", "layout", "built_ins", "furniture", "surfaces", "lighting", "instances"],
      "additionalProperties": false,
      "properties": {
        "id": {"$ref": "#/$defs/subspace_id"},
        "name": {"$ref": "#/$defs/text"},
        "count": {"type": "integer", "minimum": 1},
        "arrangement": {"$ref": "#/$defs/text"},
        "decks": {"type": "array", "minItems": 1, "uniqueItems": true, "items": {"$ref": "#/$defs/text"}},
        "dimensions": {"$ref": "#/$defs/dimensions"},
        "zones": {"type": "array", "items": {"$ref": "#/$defs/zone"}},
        "layout": {"$ref": "#/$defs/layout"},
        "built_ins": {"type": "array", "items": {"$ref": "#/$defs/built_in"}},
        "furniture": {"type": "array", "items": {"$ref": "#/$defs/furniture"}},
        "surfaces": {"type": "array", "minItems": 1, "items": {"$ref": "#/$defs/space_surface"}},
        "lighting": {"type": "array", "items": {"$ref": "#/$defs/light_source"}},
        "instances": {"type": "array", "items": {"$ref": "#/$defs/instance"}}
      },
      "allOf": [
        {"if": {"required": ["id"], "properties": {"id": {"pattern": "^INT"}}}, "then": {"properties": {"lighting": {"items": {"$ref": "#/$defs/room_light"}}}}},
        {"if": {"required": ["id"], "properties": {"id": {"pattern": "^EXT"}}}, "then": {"properties": {"lighting": {"items": {"$ref": "#/$defs/exterior_light"}}}}}
      ]
    },
    "spaces": {
      "type": "array", "minItems": 11,
      "items": {"$ref": "#/$defs/space"},
      "allOf": [
        {"contains": {"required": ["id"], "properties": {"id": {"pattern": "^INT"}}}, "minContains": 10},
        {"contains": {"required": ["id"], "properties": {"id": {"pattern": "^EXT"}}}}
      ]
    },
    "space": {
      "type": "object",
      "required": ["id", "name", "decks", "position", "dimensions", "use", "activities", "privacy", "built_ins", "furniture", "surfaces"],
      "additionalProperties": false,
      "properties": {
        "id": {"$ref": "#/$defs/space_id"},
        "name": {"$ref": "#/$defs/text"},
        "decks": {"type": "array", "minItems": 1, "uniqueItems": true, "items": {"$ref": "#/$defs/text"}},
        "position": {
          "type": "object", "required": ["x_from", "x_to", "y_min", "y_max", "relation"], "additionalProperties": false,
          "properties": {
            "x_from": {"type": "number", "minimum": 0, "maximum": 1}, "x_to": {"type": "number", "minimum": 0, "maximum": 1},
            "y_min": {"type": "number"}, "y_max": {"type": "number"}, "relation": {"$ref": "#/$defs/text"}
          }
        },
        "dimensions": {"$ref": "#/$defs/dimensions"},
        "use": {"$ref": "#/$defs/text"},
        "activities": {"type": "array", "minItems": 1, "items": {"$ref": "#/$defs/text"}},
        "privacy": {"enum": ["private", "guests", "crew", "mixed"]},
        "form": {"$ref": "#/$defs/text"},
        "zones": {"type": "array", "items": {"$ref": "#/$defs/zone"}},
        "layout": {"$ref": "#/$defs/layout"},
        "built_ins": {"type": "array", "items": {"$ref": "#/$defs/built_in"}},
        "furniture": {"type": "array", "items": {"$ref": "#/$defs/furniture"}},
        "surfaces": {"type": "array", "minItems": 1, "items": {"$ref": "#/$defs/space_surface"}},
        "palette": {"type": "array", "minItems": 2, "maxItems": 4, "items": {"$ref": "#/$defs/hex"}},
        "signature_detail": {"$ref": "#/$defs/text"},
        "lighting": {"type": "array", "items": {"$ref": "#/$defs/light_source"}},
        "quantities": {
          "type": "array",
          "items": {
            "type": "object", "required": ["item", "value", "basis"], "additionalProperties": false,
            "properties": {"item": {"$ref": "#/$defs/text"}, "value": {"type": "integer", "minimum": 0}, "basis": {"$ref": "#/$defs/count_basis"}}
          }
        },
        "set_states": {
          "type": "object", "required": ["bare", "fitout"], "additionalProperties": false,
          "properties": {"bare": {"$ref": "#/$defs/text"}, "fitout": {"$ref": "#/$defs/text"}}
        },
        "subspaces": {"type": "array", "items": {"$ref": "#/$defs/subspace"}},
        "points": {"$ref": "#/$defs/points"}
      },
      "allOf": [
        {
          "if": {"required": ["id"], "properties": {"id": {"pattern": "^INT"}}},
          "then": {"required": ["zones", "layout", "palette", "signature_detail", "lighting"], "not": {"required": ["form"]}, "properties": {"lighting": {"items": {"$ref": "#/$defs/room_light"}}}}
        },
        {
          "if": {"required": ["id"], "properties": {"id": {"pattern": "^EXT"}}},
          "then": {"required": ["form"], "properties": {"palette": false, "signature_detail": false, "set_states": false, "lighting": {"items": {"$ref": "#/$defs/exterior_light"}}}}
        }
      ]
    },

    "opening_wall": {"type": "object", "required": ["width_m", "height_m"], "additionalProperties": false, "properties": {"width_m": {"$ref": "#/$defs/measure"}, "height_m": {"$ref": "#/$defs/measure"}}},
    "opening_plan": {"type": "object", "required": ["length_m", "width_m"], "additionalProperties": false, "properties": {"length_m": {"$ref": "#/$defs/measure"}, "width_m": {"$ref": "#/$defs/measure"}}},
    "opening_size": {"oneOf": [{"$ref": "#/$defs/opening_wall"}, {"$ref": "#/$defs/opening_plan"}]},
    "exterior_face": {
      "type": "object",
      "required": ["part", "facing", "x_from", "x_to", "y_min", "y_max", "z_min", "z_max", "count", "arrangement"],
      "additionalProperties": false,
      "properties": {
        "part": {"$ref": "#/$defs/part_id"},
        "facing": {"$ref": "#/$defs/facing"},
        "x_from": {"type": "number", "minimum": 0, "maximum": 1}, "x_to": {"type": "number", "minimum": 0, "maximum": 1},
        "y_min": {"type": "number"}, "y_max": {"type": "number"}, "z_min": {"type": "number"}, "z_max": {"type": "number"},
        "count": {"type": "integer", "minimum": 1},
        "arrangement": {"$ref": "#/$defs/text"}
      }
    },
    "connection": {
      "type": "object", "required": ["id", "kind", "between", "users"], "additionalProperties": false,
      "properties": {
        "id": {"$ref": "#/$defs/connection_id"},
        "kind": {"enum": ["adjacent", "door", "opening", "stair", "lift", "ramp", "hatch", "window", "skylight"]},
        "between": {"type": "array", "minItems": 2, "maxItems": 2, "items": {"$ref": "#/$defs/endpoint"}},
        "users": {"type": "array", "uniqueItems": true, "items": {"$ref": "#/$defs/user"}},
        "landings": {"type": "array", "uniqueItems": true, "items": {"$ref": "#/$defs/text"}},
        "note": {"$ref": "#/$defs/text"},
        "exterior_face": {"$ref": "#/$defs/exterior_face"},
        "opening_size": {"$ref": "#/$defs/opening_size"},
        "set_in": {"enum": ["deck", "wall"]},
        "admits_daylight": {"type": "boolean"},
        "closure": {"oneOf": [{"$ref": "#/$defs/part_id"}, {"type": "null"}]},
        "description": {"$ref": "#/$defs/text"}
      },
      "allOf": [
        {
          "if": {"required": ["kind"], "properties": {"kind": {"enum": ["window", "skylight"]}}},
          "then": {"required": ["note", "opening_size", "admits_daylight", "description"], "properties": {"users": {"maxItems": 0}, "admits_daylight": {"const": true}, "closure": {"type": "null"}}}
        },
        {
          "if": {"required": ["kind"], "properties": {"kind": {"const": "adjacent"}}},
          "then": {"properties": {"users": {"maxItems": 0}, "between": {"items": {"$ref": "#/$defs/place_id"}}}, "not": {"anyOf": [{"required": ["exterior_face"]}, {"required": ["opening_size"]}, {"required": ["closure"]}, {"required": ["landings"]}, {"required": ["admits_daylight"]}]}}
        },
        {
          "if": {"required": ["kind"], "properties": {"kind": {"enum": ["door", "opening", "stair", "lift", "ramp", "hatch"]}}},
          "then": {"required": ["note", "admits_daylight", "closure"], "properties": {"users": {"minItems": 1}}}
        },
        {
          "if": {"required": ["kind"], "properties": {"kind": {"const": "window"}}},
          "then": {"properties": {"opening_size": {"$ref": "#/$defs/opening_wall"}}}
        },
        {
          "if": {"required": ["kind"], "properties": {"kind": {"const": "skylight"}}},
          "then": {"properties": {"opening_size": {"$ref": "#/$defs/opening_plan"}}}
        },
        {
          "if": {"required": ["kind"], "properties": {"kind": {"enum": ["door", "opening"]}}},
          "then": {"required": ["opening_size"], "properties": {"opening_size": {"$ref": "#/$defs/opening_wall"}}}
        },
        {
          "if": {"required": ["kind"], "properties": {"kind": {"const": "door"}}},
          "then": {"required": ["description"]}
        },
        {
          "if": {"required": ["kind"], "properties": {"kind": {"const": "hatch"}}},
          "then": {"required": ["opening_size", "set_in"]},
          "else": {"not": {"required": ["set_in"]}}
        },
        {
          "if": {"required": ["kind", "set_in"], "properties": {"kind": {"const": "hatch"}, "set_in": {"const": "deck"}}},
          "then": {"properties": {"opening_size": {"$ref": "#/$defs/opening_plan"}, "exterior_face": {"properties": {"facing": {"enum": ["up", "down"]}}}}}
        },
        {
          "if": {"required": ["kind", "set_in"], "properties": {"kind": {"const": "hatch"}, "set_in": {"const": "wall"}}},
          "then": {"properties": {"opening_size": {"$ref": "#/$defs/opening_wall"}, "exterior_face": {"properties": {"facing": {"not": {"enum": ["up", "down"]}}}}}}
        },
        {
          "if": {"required": ["kind"], "properties": {"kind": {"enum": ["stair", "lift"]}}},
          "then": {"required": ["landings"], "properties": {"landings": {"minItems": 2}}}
        },
        {
          "if": {"required": ["between"], "properties": {"between": {"contains": {"const": "OUTSIDE"}}}},
          "then": {"required": ["exterior_face"], "properties": {"kind": {"enum": ["window", "skylight"]}}}
        }
      ]
    },
    "route": {
      "type": "object", "required": ["id", "purpose", "users", "spaces", "via"], "additionalProperties": false,
      "properties": {
        "id": {"type": "string", "pattern": "^R[0-9]{2,3}$"},
        "purpose": {"$ref": "#/$defs/text"},
        "users": {"type": "array", "minItems": 1, "uniqueItems": true, "items": {"$ref": "#/$defs/user"}},
        "spaces": {"type": "array", "minItems": 2, "items": {"anyOf": [{"$ref": "#/$defs/place_id"}, {"const": "SEA"}]}},
        "via": {"type": "array", "minItems": 1, "items": {"$ref": "#/$defs/connection_id"}}
      }
    },

    "innovation": {
      "type": "object",
      "required": ["id", "name", "purpose", "position", "geometry", "visible_expression", "effect", "mounted_in", "serves", "effect_in", "parts", "modes", "use_sequence", "vantage", "from_state", "measures", "visible_elements", "points", "risks"],
      "additionalProperties": false,
      "properties": {
        "id": {"$ref": "#/$defs/innovation_id"},
        "name": {"$ref": "#/$defs/text"},
        "purpose": {"$ref": "#/$defs/text"},
        "position": {"$ref": "#/$defs/text"},
        "geometry": {"$ref": "#/$defs/text"},
        "visible_expression": {"$ref": "#/$defs/text"},
        "effect": {"$ref": "#/$defs/text_or_null"},
        "mounted_in": {"type": "array", "minItems": 1, "uniqueItems": true, "items": {"$ref": "#/$defs/place_id"}},
        "serves": {"type": "array", "uniqueItems": true, "items": {"$ref": "#/$defs/place_id"}},
        "effect_in": {"type": "array", "uniqueItems": true, "items": {"$ref": "#/$defs/place_id"}},
        "parts": {"type": "array", "uniqueItems": true, "items": {"$ref": "#/$defs/part_id"}},
        "modes": {
          "type": "array",
          "items": {
            "type": "object", "required": ["id", "name", "configurations", "effect"], "additionalProperties": false,
            "properties": {
              "id": {"$ref": "#/$defs/mode_id"},
              "name": {"$ref": "#/$defs/text"},
              "configurations": {"type": "array", "minItems": 1, "uniqueItems": true, "items": {"$ref": "#/$defs/configuration_id"}},
              "effect": {"$ref": "#/$defs/text_or_null"}
            }
          }
        },
        "use_sequence": {"type": "array", "items": {"$ref": "#/$defs/text"}},
        "vantage": {"type": "array", "uniqueItems": true, "items": {"$ref": "#/$defs/place_id"}},
        "from_state": {"oneOf": [{"$ref": "#/$defs/physical_state"}, {"type": "null"}]},
        "measures": {"type": "object", "propertyNames": {"pattern": "^[a-z][a-z0-9_]*$"}, "additionalProperties": {"$ref": "#/$defs/innovation_measure"}},
        "visible_elements": {
          "type": "array",
          "items": {
            "type": "object", "required": ["element", "part", "count", "arrangement", "basis", "measures", "facing"], "additionalProperties": false,
            "properties": {
              "element": {"$ref": "#/$defs/text"},
              "part": {"oneOf": [{"$ref": "#/$defs/part_id"}, {"type": "null"}]},
              "count": {"type": "integer", "minimum": 1},
              "arrangement": {"$ref": "#/$defs/text"},
              "basis": {"$ref": "#/$defs/count_basis"},
              "measures": {"type": "array", "uniqueItems": true, "items": {"$ref": "#/$defs/snake"}},
              "facing": {"$ref": "#/$defs/facing"}
            }
          }
        },
        "points": {"$ref": "#/$defs/points"},
        "risks": {"type": "array", "items": {"$ref": "#/$defs/text"}}
      },
      "if": {"required": ["effect"], "properties": {"effect": {"type": "null"}}},
      "then": {"properties": {"effect_in": {"maxItems": 0}}}
    },

    "condition": {
      "type": "object", "required": ["quantity", "comparator", "value"], "additionalProperties": false,
      "properties": {
        "quantity": {"enum": ["speed", "wind", "significant_wave_height", "sea_state"], "description": "speed and wind in kn, significant_wave_height in m, sea_state on the Douglas scale"},
        "comparator": {"enum": ["<", "<="]},
        "value": {"type": "number", "minimum": 0}
      },
      "if": {"required": ["quantity"], "properties": {"quantity": {"const": "sea_state"}}},
      "then": {"properties": {"value": {"type": "integer", "maximum": 9}}}
    },
    "limit": {
      "type": "object",
      "required": ["id", "feature", "applies_to", "conditions", "requires", "procedures", "governs", "otherwise", "otherwise_configurations", "static_display", "basis"],
      "additionalProperties": false,
      "properties": {
        "id": {"$ref": "#/$defs/limit_id"},
        "feature": {"$ref": "#/$defs/snake"},
        "applies_to": {
          "type": "object", "required": ["kind", "id"], "additionalProperties": false,
          "properties": {"kind": {"enum": ["innovation", "part", "space", "connection", "activity"]}, "id": {"oneOf": [{"$ref": "#/$defs/text"}, {"type": "null"}]}},
          "allOf": [
            {"if": {"properties": {"kind": {"const": "activity"}}}, "then": {"properties": {"id": {"type": "null"}}}},
            {"if": {"properties": {"kind": {"const": "innovation"}}}, "then": {"properties": {"id": {"$ref": "#/$defs/innovation_id"}}}},
            {"if": {"properties": {"kind": {"const": "part"}}}, "then": {"properties": {"id": {"$ref": "#/$defs/part_id"}}}},
            {"if": {"properties": {"kind": {"const": "space"}}}, "then": {"properties": {"id": {"$ref": "#/$defs/space_id"}}}},
            {"if": {"properties": {"kind": {"const": "connection"}}}, "then": {"properties": {"id": {"$ref": "#/$defs/connection_id"}}}}
          ]
        },
        "conditions": {"type": "array", "items": {"$ref": "#/$defs/condition"}},
        "requires": {"type": "array", "uniqueItems": true, "items": {"enum": ["at_anchor", "in_port", "sheltered_water"]}},
        "procedures": {"type": "array", "uniqueItems": true, "items": {"$ref": "#/$defs/snake"}},
        "governs": {"type": "array", "uniqueItems": true, "items": {"$ref": "#/$defs/configuration_id"}},
        "otherwise": {"$ref": "#/$defs/text"},
        "otherwise_configurations": {"type": "array", "uniqueItems": true, "items": {"$ref": "#/$defs/configuration_id"}},
        "static_display": {"type": "boolean"},
        "basis": {"$ref": "#/$defs/text"}
      },
      "anyOf": [
        {"properties": {"conditions": {"minItems": 1}}},
        {"properties": {"requires": {"minItems": 1}}},
        {"properties": {"procedures": {"minItems": 1}}}
      ],
      "if": {"required": ["applies_to"], "properties": {"applies_to": {"required": ["kind"], "properties": {"kind": {"const": "activity"}}}}},
      "then": {"properties": {"governs": {"maxItems": 0}}}
    },

    "design_stage": {
      "type": "object", "required": ["id", "kind", "text", "refs", "setting_brief", "participant_roles", "outcome"], "additionalProperties": false,
      "properties": {
        "id": {"$ref": "#/$defs/state"},
        "kind": {"enum": ["concept", "drawings", "model", "design_review", "handover"]},
        "text": {"$ref": "#/$defs/text"},
        "refs": {"type": "array", "uniqueItems": true, "items": {"$ref": "#/$defs/design_ref"}},
        "setting_brief": {"$ref": "#/$defs/text"},
        "participant_roles": {"type": "array", "uniqueItems": true, "items": {"$ref": "#/$defs/text"}},
        "outcome": {"$ref": "#/$defs/text"},
        "model_medium": {"enum": ["physical", "digital"]},
        "scale_denominator": {"type": "integer", "minimum": 2}
      },
      "if": {"required": ["model_medium"], "properties": {"model_medium": {"const": "digital"}}},
      "then": {"not": {"required": ["scale_denominator"]}}
    },
    "plain_design_stage": {"not": {"anyOf": [{"required": ["model_medium"]}, {"required": ["scale_denominator"]}]}},
    "surface_group": {"oneOf": [{"enum": ["bare_steel", "steel_primer", "raw_aluminium", "filler_primer", "final"]}, {"type": "null"}]},
    "build_state": {
      "type": "object", "required": ["id", "kind", "surfaces", "in_progress", "exceptions", "temporary", "surface"], "additionalProperties": false,
      "properties": {
        "id": {"$ref": "#/$defs/physical_state"},
        "kind": {"enum": ["build", "finished"]},
        "surfaces": {
          "type": "object", "required": ["hull", "superstructure", "decks", "glazing"], "additionalProperties": false,
          "properties": {
            "hull": {"$ref": "#/$defs/surface_group"},
            "superstructure": {"$ref": "#/$defs/surface_group"},
            "decks": {"$ref": "#/$defs/surface_group"},
            "glazing": {"enum": ["none", "open_frames", "protective_film", "final_glass"]}
          }
        },
        "in_progress": {
          "type": "array",
          "items": {
            "type": "object", "required": ["part", "description"], "additionalProperties": false,
            "properties": {"part": {"$ref": "#/$defs/part_id"}, "description": {"$ref": "#/$defs/text"}}
          }
        },
        "exceptions": {
          "type": "array",
          "items": {
            "type": "object", "required": ["part", "presence", "configuration", "description"], "additionalProperties": false,
            "properties": {
              "part": {"$ref": "#/$defs/part_id"},
              "presence": {"enum": ["removed", "present"]},
              "configuration": {"oneOf": [{"$ref": "#/$defs/configuration_id"}, {"type": "null"}]},
              "description": {"$ref": "#/$defs/text"}
            }
          }
        },
        "temporary": {"type": "array", "uniqueItems": true, "items": {"enum": ["keel_blocks", "cradle", "scaffolding"]}},
        "surface": {"$ref": "#/$defs/text_or_null"}
      }
    },
    "build_states": {
      "type": "array", "minItems": 12, "maxItems": 12,
      "prefixItems": [
        {"allOf": [{"$ref": "#/$defs/design_stage"}, {"$ref": "#/$defs/plain_design_stage"}, {"properties": {"id": {"const": "BS01"}, "kind": {"const": "concept"}}}]},
        {"allOf": [{"$ref": "#/$defs/design_stage"}, {"$ref": "#/$defs/plain_design_stage"}, {"properties": {"id": {"const": "BS02"}, "kind": {"const": "drawings"}}}]},
        {"allOf": [{"$ref": "#/$defs/design_stage"}, {"required": ["model_medium"], "properties": {"id": {"const": "BS03"}, "kind": {"const": "model"}}}]},
        {"allOf": [{"$ref": "#/$defs/design_stage"}, {"$ref": "#/$defs/plain_design_stage"}, {"properties": {"id": {"const": "BS04"}, "kind": {"const": "design_review"}}}]},
        {"allOf": [{"$ref": "#/$defs/design_stage"}, {"$ref": "#/$defs/plain_design_stage"}, {"properties": {"id": {"const": "BS05"}, "kind": {"const": "handover"}}}]},
        {"allOf": [{"$ref": "#/$defs/build_state"}, {"properties": {"id": {"const": "BS06"}, "kind": {"const": "build"}, "surface": {"$ref": "#/$defs/text"}}}]},
        {"allOf": [{"$ref": "#/$defs/build_state"}, {"properties": {"id": {"const": "BS07"}, "kind": {"const": "build"}, "surface": {"$ref": "#/$defs/text"}}}]},
        {"allOf": [{"$ref": "#/$defs/build_state"}, {"properties": {"id": {"const": "BS08"}, "kind": {"const": "build"}, "surface": {"$ref": "#/$defs/text"}}}]},
        {"allOf": [{"$ref": "#/$defs/build_state"}, {"properties": {"id": {"const": "BS09"}, "kind": {"const": "build"}, "surface": {"$ref": "#/$defs/text"}}}]},
        {"allOf": [{"$ref": "#/$defs/build_state"}, {"properties": {"id": {"const": "BS10"}, "kind": {"const": "build"}, "surface": {"$ref": "#/$defs/text"}}}]},
        {"allOf": [{"$ref": "#/$defs/build_state"}, {"properties": {"id": {"const": "BS11"}, "kind": {"const": "finished"}, "surface": {"type": "null"}}}]},
        {"allOf": [{"$ref": "#/$defs/build_state"}, {"properties": {"id": {"const": "BS12"}, "kind": {"const": "finished"}, "surface": {"type": "null"}, "temporary": {"maxItems": 0}}}]}
      ],
      "items": false
    },

    "identity_rule": {
      "type": "object", "required": ["id", "kind", "scope", "description", "refs", "from_state"], "additionalProperties": false,
      "properties": {
        "id": {"$ref": "#/$defs/rule_id"},
        "kind": {"enum": ["must_keep", "must_not"]},
        "scope": {"type": "array", "minItems": 1, "uniqueItems": true, "items": {"anyOf": [{"const": "YACHT"}, {"$ref": "#/$defs/space_id"}]}},
        "description": {"type": "string", "minLength": 1, "maxLength": 240, "pattern": "^(?!([Dd]o [Nn]ot|[Nn]o|[Nn]ot)\\\\b)\\\\S"},
        "refs": {"type": "array", "uniqueItems": true, "items": {"anyOf": [{"$ref": "#/$defs/part_id"}, {"$ref": "#/$defs/place_id"}, {"$ref": "#/$defs/innovation_id"}]}},
        "from_state": {"oneOf": [{"$ref": "#/$defs/state"}, {"type": "null"}]}
      }
    },
    "source_issue": {
      "type": "object", "required": ["id", "paths", "problem", "impact", "blocking"], "additionalProperties": false,
      "properties": {
        "id": {"$ref": "#/$defs/issue_id"},
        "paths": {"type": "array", "minItems": 1, "items": {"$ref": "#/$defs/text"}},
        "problem": {"$ref": "#/$defs/text"},
        "impact": {"$ref": "#/$defs/text"},
        "blocking": {"type": "boolean"}
      }
    },
    "blocking_issue": {"type": "object", "required": ["blocking"], "properties": {"blocking": {"const": true}}},

    "camera": {
      "type": "object", "required": ["azimuth_deg", "elevation_deg", "projection"], "additionalProperties": false,
      "properties": {
        "azimuth_deg": {"oneOf": [{"type": "number", "minimum": 0, "exclusiveMaximum": 360}, {"type": "null"}]},
        "elevation_deg": {"oneOf": [{"type": "number", "minimum": -90, "maximum": 90}, {"type": "null"}]},
        "projection": {"enum": ["orthographic", "perspective"]},
        "lens_mm": {"type": "number", "exclusiveMinimum": 0},
        "bow": {"$ref": "#/$defs/text"}
      }
    },
    "view": {
      "type": "object", "required": ["id", "camera", "target", "visible", "partial", "uncertain", "issues"], "additionalProperties": false,
      "properties": {
        "id": {"enum": ["MS1", "MS2", "MS3", "MS4", "MS5", "MS6", "MS7", "MS8"]},
        "camera": {"$ref": "#/$defs/camera"},
        "target": {"$ref": "#/$defs/text"},
        "visible": {"type": "array", "uniqueItems": true, "items": {"$ref": "#/$defs/view_ref"}},
        "partial": {"type": "array", "uniqueItems": true, "items": {"$ref": "#/$defs/view_ref"}},
        "uncertain": {"type": "array", "uniqueItems": true, "items": {"$ref": "#/$defs/view_ref"}},
        "issues": {"type": "array", "uniqueItems": true, "items": {"$ref": "#/$defs/issue_id"}}
      }
    },
    "model_sheet": {
      "type": "object", "required": ["display_configuration", "views", "final_prompt"], "additionalProperties": false,
      "properties": {
        "display_configuration": {"type": "array", "uniqueItems": true, "items": {"$ref": "#/$defs/configuration_id"}},
        "views": {
          "type": "array", "minItems": 8, "maxItems": 8,
          "prefixItems": [
            {"allOf": [{"$ref": "#/$defs/view"}, {"properties": {"id": {"const": "MS1"}}}]},
            {"allOf": [{"$ref": "#/$defs/view"}, {"properties": {"id": {"const": "MS2"}}}]},
            {"allOf": [{"$ref": "#/$defs/view"}, {"properties": {"id": {"const": "MS3"}}}]},
            {"allOf": [{"$ref": "#/$defs/view"}, {"properties": {"id": {"const": "MS4"}}}]},
            {"allOf": [{"$ref": "#/$defs/view"}, {"properties": {"id": {"const": "MS5"}}}]},
            {"allOf": [{"$ref": "#/$defs/view"}, {"properties": {"id": {"const": "MS6"}}}]},
            {"allOf": [{"$ref": "#/$defs/view"}, {"properties": {"id": {"const": "MS7"}}}]},
            {"allOf": [{"$ref": "#/$defs/view"}, {"properties": {"id": {"const": "MS8"}, "camera": {"properties": {"azimuth_deg": {"type": "number"}, "elevation_deg": {"type": "number"}}}}}]}
          ],
          "items": false
        },
        "final_prompt": {"$ref": "#/$defs/text"}
      }
    }
  }
}
