      'schema_sha256' => '424a468e536b78424a8c3461dd1ba3b73cc706f8048472128257a156acfaf688',
      'source_file' => 'release:phase-3-design-v9/Phase3Design.schema.json',
      'json_schema_id' => 'https://superyacht.local/schemas/Phase3Design',
      'json_schema_dialect' => 'https://json-schema.org/draft/2020-12/schema',
