    32 => 
    array (
      'id' => 'a31f28be-df0c-495d-8d37-57edb3568385',
      'namespace' => 'moto',
      'schema_key' => 'MotoEvidence',
      'version' => '1.0.0',
      'name' => 'Moto Phase 1 — inspiration evidence (moto-evidence-v1)',
      'schema_content' => '{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://superyacht.local/schemas/MotoEvidence",
  "title": "Moto Phase 1 — inspiration evidence (moto-evidence-v1)",
  "description": "One answer of Phase 1 for a custom motorcycle: the subject the article is about and its platform, the base apart from the build, what the article states about that subject with verbatim evidence for every value, the open source issues and the eight self-checks. Evidence is checked against the article; nothing here is verified as true outside the article.",
  "type": "object",
  "additionalProperties": false,
  "required": ["format", "subject", "inspiration", "issues", "self_check"],
  "properties": {
    "format": { "const": "moto-evidence-v1" },
    "subject": {
      "type": "object",
      "additionalProperties": false,
      "required": ["article_kind", "status", "primary", "platform", "basis", "others"],
      "properties": {
        "article_kind": { "enum": ["single_bike", "multiple_bikes", "product_line", "not_a_motorcycle"] },
        "status": { "enum": ["identified", "ambiguous", "none"] },
        "primary": { "type": ["string", "null"], "minLength": 1 },
        "platform": { "enum": ["harley_davidson", "other", "unknown"] },
        "basis": { "type": "array", "items": { "$ref": "#/$defs/evidence" } },
        "others": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": ["name", "relation", "evidence"],
            "properties": {
              "name": { "type": "string", "minLength": 1 },
              "relation": { "enum": ["donor", "base_model", "earlier_build", "sister", "comparison", "other"] },
              "evidence": { "$ref": "#/$defs/evidenceList" }
            }
          }
        }
      },
      "allOf": [
        { "if": { "properties": { "status": { "const": "identified" } } }, "then": { "properties": { "primary": { "type": "string" }, "basis": { "minItems": 1 } } } },
        { "if": { "properties": { "status": { "const": "ambiguous" } } }, "then": { "properties": { "primary": { "type": "null" } } } },
        { "if": { "properties": { "status": { "const": "none" } } }, "then": { "properties": { "primary": { "type": "null" } } } },
        { "if": { "properties": { "article_kind": { "const": "not_a_motorcycle" } } }, "then": { "properties": { "status": { "const": "none" } } } }
      ]
    },
    "inspiration": {
      "type": "object",
      "additionalProperties": false,
      "required": ["source_identity", "base", "styling", "chassis", "powertrain", "technology", "specs", "intent", "visuals", "claims"],
      "properties": {
        "source_identity": {
          "type": "object",
          "additionalProperties": false,
          "required": ["name", "builder", "designers", "style", "silhouette", "colors", "signatures"],
          "properties": {
            "name": { "$ref": "#/$defs/quoted" },
            "builder": { "$ref": "#/$defs/quoted" },
            "designers": { "$ref": "#/$defs/quotedList" },
            "style": { "$ref": "#/$defs/quoted" },
            "silhouette": { "$ref": "#/$defs/quoted" },
            "colors": { "$ref": "#/$defs/quoted" },
            "signatures": { "type": "array", "items": { "allOf": [{ "$ref": "#/$defs/item" }, { "properties": { "id": { "pattern": "^S[0-9]{2,}$" } } }] } }
          }
        },
        "base": {
          "type": "object",
          "additionalProperties": false,
          "required": ["make", "model", "model_year", "engine_family", "engine"],
          "properties": {
            "make": { "$ref": "#/$defs/quoted" },
            "model": { "$ref": "#/$defs/quoted" },
            "model_year": { "$ref": "#/$defs/quoted" },
            "engine_family": { "$ref": "#/$defs/quoted" },
            "engine": { "$ref": "#/$defs/quoted" }
          }
        },
        "styling": { "type": "array", "items": { "allOf": [{ "$ref": "#/$defs/item" }, { "properties": { "id": { "pattern": "^X[0-9]{2,}$" } } }] } },
        "chassis": { "type": "array", "items": { "allOf": [{ "$ref": "#/$defs/item" }, { "properties": { "id": { "pattern": "^K[0-9]{2,}$" } } }] } },
        "powertrain": { "type": "array", "items": { "allOf": [{ "$ref": "#/$defs/item" }, { "properties": { "id": { "pattern": "^P[0-9]{2,}$" } } }] } },
        "technology": { "type": "array", "items": { "allOf": [{ "$ref": "#/$defs/item" }, { "properties": { "id": { "pattern": "^T[0-9]{2,}$" } } }] } },
        "specs": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": ["id", "quantity", "value", "applies_to", "evidence"],
            "properties": {
              "id": { "type": "string", "pattern": "^M[0-9]{2,}$" },
              "quantity": { "type": "string", "pattern": "^[a-z][a-z0-9_]*$" },
              "value": { "type": "string", "minLength": 1 },
              "applies_to": { "$ref": "#/$defs/scope" },
              "evidence": { "$ref": "#/$defs/evidenceList" }
            }
          }
        },
        "intent": {
          "oneOf": [
            { "type": "null" },
            {
              "type": "object",
              "additionalProperties": false,
              "required": ["text", "evidence"],
              "properties": {
                "text": { "type": "string", "minLength": 1 },
                "evidence": { "$ref": "#/$defs/evidenceList" }
              }
            }
          ]
        },
        "visuals": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": ["id", "description", "evidence"],
            "properties": {
              "id": { "type": "string", "pattern": "^V[0-9]{2,}$" },
              "description": { "type": "string", "minLength": 1 },
              "evidence": { "type": "array", "minItems": 1, "items": { "allOf": [{ "$ref": "#/$defs/evidence" }, { "properties": { "source": { "const": "caption" } } }] } }
            }
          }
        },
        "claims": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": ["id", "claim", "evidence"],
            "properties": {
              "id": { "type": "string", "pattern": "^C[0-9]{2,}$" },
              "claim": { "type": "string", "minLength": 1 },
              "evidence": { "$ref": "#/$defs/evidenceList" }
            }
          }
        }
      }
    },
    "issues": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["kind", "field", "message", "evidence"],
        "properties": {
          "kind": { "enum": ["missing", "ambiguous", "conflict"] },
          "field": { "type": "string", "pattern": "^(subject(\\\\.(article_kind|status|primary|platform|basis|others))?|inspiration\\\\.intent|inspiration\\\\.base\\\\.(make|model|model_year|engine_family|engine)|inspiration\\\\.source_identity\\\\.(name|builder|designers|style|silhouette|colors|signatures(\\\\.S[0-9]{2,})?)|inspiration\\\\.styling(\\\\.X[0-9]{2,})?|inspiration\\\\.chassis(\\\\.K[0-9]{2,})?|inspiration\\\\.powertrain(\\\\.P[0-9]{2,})?|inspiration\\\\.technology(\\\\.T[0-9]{2,})?|inspiration\\\\.specs(\\\\.M[0-9]{2,})?|inspiration\\\\.visuals(\\\\.V[0-9]{2,})?|inspiration\\\\.claims(\\\\.C[0-9]{2,})?)$" },
          "message": { "type": "string", "minLength": 1 },
          "evidence": { "type": "array", "items": { "$ref": "#/$defs/evidence" } }
        },
        "allOf": [
          { "if": { "properties": { "kind": { "const": "conflict" } } }, "then": { "properties": { "evidence": { "minItems": 1 } } } }
        ]
      }
    },
    "self_check": {
      "type": "array",
      "minItems": 8,
      "prefixItems": [
        { "allOf": [{ "$ref": "#/$defs/check" }, { "properties": { "check": { "const": "subject" } } }] },
        { "allOf": [{ "$ref": "#/$defs/check" }, { "properties": { "check": { "const": "evidence" } } }] },
        { "allOf": [{ "$ref": "#/$defs/check" }, { "properties": { "check": { "const": "completeness" } } }] },
        { "allOf": [{ "$ref": "#/$defs/check" }, { "properties": { "check": { "const": "no_inference" } } }] },
        { "allOf": [{ "$ref": "#/$defs/check" }, { "properties": { "check": { "const": "no_duplicates" } } }] },
        { "allOf": [{ "$ref": "#/$defs/check" }, { "properties": { "check": { "const": "measurements" } } }] },
        { "allOf": [{ "$ref": "#/$defs/check" }, { "properties": { "check": { "const": "captions" } } }] },
        { "allOf": [{ "$ref": "#/$defs/check" }, { "properties": { "check": { "const": "contract" } } }] }
      ],
      "items": false
    }
  },
  "allOf": [
    { "if": { "required": ["self_check"], "properties": { "self_check": { "contains": { "required": ["result"], "properties": { "result": { "const": "open" } } } } } }, "then": { "properties": { "issues": { "minItems": 1 } } } },
    { "if": { "required": ["subject"], "properties": { "subject": { "required": ["status"], "properties": { "status": { "const": "ambiguous" } } } } }, "then": { "properties": { "issues": { "contains": { "required": ["kind", "field"], "properties": { "kind": { "const": "ambiguous" }, "field": { "pattern": "^subject(\\\\.|$)" } } } } } } }
  ],
  "$defs": {
    "source": { "enum": ["headline", "body", "caption", "table", "metadata"] },
    "scope": { "enum": ["primary", "base", "product_line"] },
    "evidence": {
      "type": "object",
      "additionalProperties": false,
      "required": ["quote", "source"],
      "properties": {
        "quote": { "type": "string", "minLength": 1 },
        "source": { "$ref": "#/$defs/source" }
      }
    },
    "evidenceList": { "type": "array", "minItems": 1, "items": { "$ref": "#/$defs/evidence" } },
    "quoted": {
      "oneOf": [
        { "type": "null" },
        {
          "type": "object",
          "additionalProperties": false,
          "required": ["value", "evidence"],
          "properties": {
            "value": { "type": "string", "minLength": 1 },
            "evidence": { "$ref": "#/$defs/evidenceList" }
          }
        }
      ]
    },
    "quotedList": {
      "oneOf": [
        { "type": "null" },
        {
          "type": "object",
          "additionalProperties": false,
          "required": ["value", "evidence"],
          "properties": {
            "value": { "type": "array", "minItems": 1, "items": { "type": "string", "minLength": 1 } },
            "evidence": { "$ref": "#/$defs/evidenceList" }
          }
        }
      ]
    },
    "item": {
      "type": "object",
      "additionalProperties": false,
      "required": ["id", "feature", "applies_to", "evidence"],
      "properties": {
        "id": { "type": "string" },
        "feature": { "type": "string", "minLength": 1 },
        "applies_to": { "$ref": "#/$defs/scope" },
        "evidence": { "$ref": "#/$defs/evidenceList" }
      }
    },
    "check": {
      "type": "object",
      "additionalProperties": false,
      "required": ["check", "result", "note"],
      "properties": {
        "check": { "type": "string" },
        "result": { "enum": ["passed", "open"] },
        "note": { "type": "string" }
      },
      "allOf": [
        { "if": { "properties": { "result": { "const": "open" } } }, "then": { "properties": { "note": { "pattern": "\\\\S" } } } }
      ]
    }
  }
}
