    33 => 
    array (
      'id' => 'a31f28c1-69ad-49dd-8a71-40e2c225e988',
      'namespace' => 'moto',
      'schema_key' => 'MotoDna',
      'version' => '1.0.0',
      'name' => 'Moto Phase 2 — custom DNA (moto-dna-v1)',
      'schema_content' => '{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://superyacht.local/schemas/MotoDna",
  "title": "Moto Phase 2 — custom DNA (moto-dna-v1)",
  "description": "One answer of Phase 2 for a Harley-Davidson custom: the resolved brief, theme, emotion, departures from the Phase 1 source, the base features the build keeps, 1-3 signature features, silhouette, must-avoid list, hero moment and the twelve self-checks the writer ran and repaired before answering. The self-checks match the DNA against the prompt; they are not proof of novelty and not an engineering approval.",
  "type": "object",
  "additionalProperties": false,
  "required": ["format", "dna", "self_check"],
  "properties": {
    "format": { "const": "moto-dna-v1" },
    "dna": {
      "type": "object",
      "additionalProperties": false,
      "required": ["brief", "theme", "emotion", "departures", "keep", "features", "silhouette", "must_avoid", "hero_moment"],
      "properties": {
        "brief": {
          "type": "object",
          "additionalProperties": false,
          "required": ["platform", "keep", "change_scope", "rider", "purpose", "limits"],
          "properties": {
            "platform": {
              "type": "object",
              "additionalProperties": false,
              "required": ["family", "model", "era", "engine_family", "basis"],
              "properties": {
                "family": { "$ref": "#/$defs/text" },
                "model": { "oneOf": [{ "$ref": "#/$defs/text" }, { "type": "null" }] },
                "era": { "$ref": "#/$defs/text" },
                "engine_family": { "$ref": "#/$defs/text" },
                "basis": { "$ref": "#/$defs/basis" }
              }
            },
            "keep": { "type": "array", "minItems": 1, "items": { "$ref": "#/$defs/text" } },
            "change_scope": { "type": "array", "minItems": 1, "items": { "$ref": "#/$defs/text" } },
            "rider": {
              "type": "object",
              "additionalProperties": false,
              "required": ["height_cm", "build", "needs", "basis"],
              "properties": {
                "height_cm": { "type": "integer", "minimum": 140, "maximum": 210 },
                "build": { "$ref": "#/$defs/text" },
                "needs": { "$ref": "#/$defs/text" },
                "basis": { "$ref": "#/$defs/basis" }
              }
            },
            "purpose": {
              "type": "object",
              "additionalProperties": false,
              "required": ["kind", "text", "basis"],
              "properties": {
                "kind": { "enum": ["show", "street", "touring", "other"] },
                "text": { "$ref": "#/$defs/text" },
                "basis": { "$ref": "#/$defs/basis" }
              }
            },
            "limits": {
              "type": "object",
              "additionalProperties": false,
              "required": ["text", "basis"],
              "properties": {
                "text": { "oneOf": [{ "$ref": "#/$defs/text" }, { "type": "null" }] },
                "basis": { "enum": ["provided", "none"] }
              },
              "allOf": [
                { "if": { "properties": { "basis": { "const": "none" } } }, "then": { "properties": { "text": { "type": "null" } } } },
                { "if": { "properties": { "basis": { "const": "provided" } } }, "then": { "properties": { "text": { "type": "string" } } } }
              ]
            }
          }
        },
        "theme": { "$ref": "#/$defs/text" },
        "emotion": { "enum": ["awe", "serenity", "power", "mystery", "freedom", "precision"] },
        "departures": {
          "type": "array",
          "minItems": 3,
          "maxItems": 5,
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": ["id", "from_id", "method", "result"],
            "properties": {
              "id": { "type": "string", "pattern": "^D[1-5]$" },
              "from_id": { "type": "string", "pattern": "^[SXKPTV][0-9]{2,}$" },
              "method": { "type": "string", "pattern": "^(CROSS-DOMAIN|INVERT|MERGE|RELOCATE|SCALE SHIFT|SUBTRACT)( \\\\+ (CROSS-DOMAIN|INVERT|MERGE|RELOCATE|SCALE SHIFT|SUBTRACT))?$" },
              "result": { "$ref": "#/$defs/text" }
            }
          }
        },
        "keep": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": ["feature", "reason"],
            "properties": {
              "feature": { "$ref": "#/$defs/text" },
              "reason": { "$ref": "#/$defs/text" }
            }
          }
        },
        "features": {
          "type": "array",
          "minItems": 1,
          "maxItems": 3,
          "contains": { "required": ["visible_at_rest"], "properties": { "visible_at_rest": { "const": true } } },
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": ["id", "name", "kind", "what", "why_new", "plausibility", "visible_at_rest"],
            "properties": {
              "id": { "type": "string", "pattern": "^F[1-3]$" },
              "name": { "$ref": "#/$defs/text" },
              "kind": { "enum": ["form", "function", "mechanism"] },
              "what": { "$ref": "#/$defs/text" },
              "why_new": { "$ref": "#/$defs/text" },
              "plausibility": { "$ref": "#/$defs/text" },
              "visible_at_rest": { "type": "boolean" }
            }
          }
        },
        "silhouette": { "$ref": "#/$defs/text" },
        "must_avoid": { "type": "array", "minItems": 8, "items": { "$ref": "#/$defs/text" } },
        "hero_moment": { "$ref": "#/$defs/text" }
      }
    },
    "self_check": {
      "type": "array",
      "minItems": 12,
      "prefixItems": [
        { "allOf": [{ "$ref": "#/$defs/check" }, { "properties": { "check": { "const": "source_floor" } } }] },
        { "allOf": [{ "$ref": "#/$defs/check" }, { "properties": { "check": { "const": "brief" } } }] },
        { "allOf": [{ "$ref": "#/$defs/check" }, { "properties": { "check": { "const": "theme" } } }] },
        { "allOf": [{ "$ref": "#/$defs/check" }, { "properties": { "check": { "const": "departures" } } }] },
        { "allOf": [{ "$ref": "#/$defs/check" }, { "properties": { "check": { "const": "features" } } }] },
        { "allOf": [{ "$ref": "#/$defs/check" }, { "properties": { "check": { "const": "plausibility" } } }] },
        { "allOf": [{ "$ref": "#/$defs/check" }, { "properties": { "check": { "const": "coherence" } } }] },
        { "allOf": [{ "$ref": "#/$defs/check" }, { "properties": { "check": { "const": "silhouette" } } }] },
        { "allOf": [{ "$ref": "#/$defs/check" }, { "properties": { "check": { "const": "must_avoid" } } }] },
        { "allOf": [{ "$ref": "#/$defs/check" }, { "properties": { "check": { "const": "history" } } }] },
        { "allOf": [{ "$ref": "#/$defs/check" }, { "properties": { "check": { "const": "hero" } } }] },
        { "allOf": [{ "$ref": "#/$defs/check" }, { "properties": { "check": { "const": "contract_and_names" } } }] }
      ],
      "items": false
    }
  },
  "$defs": {
    "text": { "type": "string", "pattern": "\\\\S" },
    "basis": { "enum": ["provided", "decided"] },
    "check": {
      "type": "object",
      "additionalProperties": false,
      "required": ["check", "result", "note"],
      "properties": {
        "check": { "type": "string" },
        "result": { "enum": ["passed", "open"] },
        "note": { "type": "string" }
      },
      "allOf": [
        { "if": { "properties": { "result": { "const": "open" } } }, "then": { "properties": { "note": { "pattern": "\\\\S" } } } }
      ]
    }
  }
}
