    36 => 
    array (
      'id' => 'a3205229-9785-4c84-834e-641fdfc5afe0',
      'namespace' => 'moto',
      'schema_key' => 'MotoScript',
      'version' => '1.0.0',
      'name' => 'Moto Phase 4 — story and script (moto-script-v1)',
      'schema_content' => '{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://superyacht.local/schemas/MotoScript",
  "title": "Moto Phase 4 — story and script (moto-script-v1)",
  "description": "One answer of Phase 4 for a custom motorcycle: the story of its build and first ride, told as the beats of a wordless film.",
  "x-word-limits": { "characters.*": 35 },
  "type": "object",
  "additionalProperties": false,
  "required": ["format", "phase", "project_id", "prompt_version", "status", "data", "flags"],
  "properties": {
    "format": { "const": "moto-script-v1" },
    "phase": { "const": "4" },
    "project_id": { "$ref": "#/$defs/text" },
    "prompt_version": { "$ref": "#/$defs/text" },
    "status": { "enum": ["ok", "partial", "fail"] },
    "data": { "type": "object" },
    "flags": { "type": "array", "items": { "$ref": "#/$defs/text" } }
  },
  "allOf": [
    {
      "if": { "properties": { "status": { "const": "fail" } } },
      "then": { "properties": { "data": { "maxProperties": 0 }, "flags": { "minItems": 1 } } },
      "else": { "properties": { "data": { "$ref": "#/$defs/data" } } }
    },
    { "if": { "properties": { "status": { "const": "partial" } } }, "then": { "properties": { "flags": { "minItems": 1 } } } }
  ],
  "$defs": {
    "text": { "type": "string", "pattern": "\\\\S" },
    "beat_id": { "type": "string", "pattern": "^B[1-9][0-9]*$" },
    "state": { "type": "string", "pattern": "^BS(0[1-9]|1[0-2])$" },
    "data": {
      "type": "object",
      "additionalProperties": false,
      "required": ["story", "characters", "beats", "text_cards", "music_brief"],
      "properties": {
        "story": { "$ref": "#/$defs/story" },
        "characters": {
          "type": "object",
          "additionalProperties": false,
          "required": ["builder", "rider"],
          "properties": { "builder": { "$ref": "#/$defs/text" }, "rider": { "$ref": "#/$defs/text" } }
        },
        "beats": { "type": "array", "minItems": 6, "maxItems": 60, "items": { "$ref": "#/$defs/beat" } },
        "text_cards": { "type": "array", "minItems": 2, "items": { "$ref": "#/$defs/card" } },
        "music_brief": { "$ref": "#/$defs/music" }
      }
    },
    "story": {
      "type": "object",
      "additionalProperties": false,
      "required": ["logline", "spine", "hero_beat", "loops", "obstacles"],
      "properties": {
        "logline": { "$ref": "#/$defs/text" },
        "spine": { "$ref": "#/$defs/text" },
        "hero_beat": { "$ref": "#/$defs/beat_id" },
        "loops": {
          "type": "array",
          "maxItems": 3,
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": ["motif", "plant", "payoff"],
            "properties": {
              "motif": { "$ref": "#/$defs/text" },
              "plant": { "$ref": "#/$defs/beat_id" },
              "payoff": { "$ref": "#/$defs/beat_id" }
            }
          }
        },
        "obstacles": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": ["id", "problem", "solution", "problem_beat", "solution_beat"],
            "properties": {
              "id": { "type": "string", "pattern": "^O[1-9][0-9]*$" },
              "problem": { "$ref": "#/$defs/text" },
              "solution": { "$ref": "#/$defs/text" },
              "problem_beat": { "$ref": "#/$defs/beat_id" },
              "solution_beat": { "$ref": "#/$defs/beat_id" }
            }
          }
        }
      }
    },
    "beat": {
      "type": "object",
      "additionalProperties": false,
      "required": ["id", "act", "state", "time_jump", "duration_s", "purpose", "visual", "location", "time_light", "reveal", "on_screen", "design_refs", "in_use", "configurations", "situation", "link", "sfx"],
      "properties": {
        "id": { "$ref": "#/$defs/beat_id" },
        "act": { "enum": ["hook", "idea", "fabrication", "finish", "experience", "hero", "ending"] },
        "state": { "anyOf": [{ "type": "null" }, { "$ref": "#/$defs/state" }] },
        "time_jump": { "enum": ["none", "flash_forward", "flashback"] },
        "duration_s": { "type": "number", "exclusiveMinimum": 0 },
        "purpose": { "$ref": "#/$defs/text" },
        "visual": { "$ref": "#/$defs/text" },
        "location": { "$ref": "#/$defs/text" },
        "time_light": { "$ref": "#/$defs/text" },
        "reveal": { "enum": ["none", "fragment", "shape", "detail", "whole"] },
        "on_screen": { "type": "array", "uniqueItems": true, "items": { "enum": ["builder", "rider"] } },
        "design_refs": { "type": "array", "uniqueItems": true, "items": { "type": "string", "pattern": "^(P[0-9]{2,3}|S[0-9]{2}|F[1-3]|M[0-9]+)$" } },
        "in_use": { "type": "array", "uniqueItems": true, "items": { "type": "string", "pattern": "^(P[0-9]{2,3}|S[0-9]{2}|F[1-3])$" } },
        "configurations": { "type": "array", "uniqueItems": true, "items": { "type": "string", "pattern": "^P[0-9]{2,3}-K[0-9]{2}$" } },
        "situation": {
          "anyOf": [
            { "type": "null" },
            {
              "type": "object",
              "additionalProperties": false,
              "required": ["mode", "engine", "side_stand", "speed_kmh", "lean_angle_deg", "dry_road", "procedures"],
              "properties": {
                "mode": { "enum": ["representation", "mockup", "in_workshop", "parked", "idling", "riding"] },
                "engine": { "enum": ["off", "running", null] },
                "side_stand": { "enum": ["up", "down", null] },
                "speed_kmh": { "type": ["number", "null"], "minimum": 0 },
                "lean_angle_deg": { "type": ["number", "null"], "minimum": 0 },
                "dry_road": { "type": ["boolean", "null"] },
                "procedures": { "type": "array", "uniqueItems": true, "items": { "type": "string", "pattern": "^[a-z][a-z0-9_]*$" } }
              }
            }
          ]
        },
        "link": { "anyOf": [{ "type": "null" }, { "$ref": "#/$defs/text" }] },
        "sfx": { "type": "array", "items": { "$ref": "#/$defs/text" } }
      },
      "if": { "properties": { "act": { "const": "ending" } } },
      "then": { "properties": { "situation": { "type": "null" } } },
      "else": { "properties": { "state": { "$ref": "#/$defs/state" } } }
    },
    "card": {
      "type": "object",
      "additionalProperties": false,
      "required": ["beat", "offset_s", "sec", "text", "type", "source_ref"],
      "properties": {
        "beat": { "$ref": "#/$defs/beat_id" },
        "offset_s": { "type": "number", "minimum": 0 },
        "sec": { "type": "number", "minimum": 1.5 },
        "text": { "$ref": "#/$defs/text" },
        "type": { "enum": ["STAGE", "SPEC", "NAME", "BASE", "DISCLAIMER", "END"] },
        "source_ref": { "anyOf": [{ "type": "null" }, { "type": "string", "pattern": "^motorcycle\\\\.(base|specs|name)(\\\\.[a-z_]+)*$" }] }
      },
      "allOf": [
        { "if": { "properties": { "type": { "enum": ["SPEC", "BASE"] } } }, "then": { "properties": { "source_ref": { "type": "string" } } } }
      ]
    },
    "music": {
      "type": "object",
      "additionalProperties": false,
      "required": ["bpm", "instruments", "energy", "hits"],
      "properties": {
        "bpm": { "type": "array", "minItems": 2, "maxItems": 2, "items": { "type": "number", "minimum": 40, "maximum": 200 } },
        "instruments": { "type": "array", "minItems": 1, "items": { "$ref": "#/$defs/text" } },
        "energy": { "$ref": "#/$defs/text" },
        "hits": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": ["moment", "beat"],
            "properties": {
              "moment": { "enum": ["hook", "build", "reveal", "first_fire", "ending"] },
              "beat": { "$ref": "#/$defs/beat_id" }
            }
          }
        }
      }
    }
  }
}
