    array (
      'id' => 'a3209720-e0da-409e-be2a-693ec360e566',
      'namespace' => 'moto',
      'schema_key' => 'MotoLocations',
      'version' => '1.0.0',
      'name' => 'Moto Phase 5 — locations and background plates (moto-locations-v1)',
      'schema_content' => '{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://superyacht.local/schemas/MotoLocations",
  "title": "Moto Phase 5 — locations and background plates (moto-locations-v1)",
  "description": "One answer of Phase 5 for a custom motorcycle film: the places the approved script uses and the background plates rendered once and reused by its shots. The motorcycle, its parts, mockups, drawings and people are added at the shot step.",
  "type": "object",
  "additionalProperties": false,
  "required": ["format", "phase", "project_id", "prompt_version", "status", "data", "flags"],
  "properties": {
    "format": { "const": "moto-locations-v1" },
    "phase": { "const": "5" },
    "project_id": { "$ref": "#/$defs/text" },
    "prompt_version": { "$ref": "#/$defs/text" },
    "status": { "enum": ["ok", "partial", "fail"] },
    "data": { "type": "object" },
    "flags": { "type": "array", "items": { "$ref": "#/$defs/text" } }
  },
  "allOf": [
    { "if": { "properties": { "status": { "const": "fail" } } }, "then": { "properties": { "data": { "maxProperties": 0 }, "flags": { "minItems": 1 } } }, "else": { "properties": { "data": { "$ref": "#/$defs/data" } } } },
    { "if": { "properties": { "status": { "const": "partial" } } }, "then": { "properties": { "flags": { "minItems": 1 } } } }
  ],
  "$defs": {
    "text": { "type": "string", "pattern": "\\\\S" },
    "texts": { "type": "array", "items": { "$ref": "#/$defs/text" } },
    "hex": { "type": "string", "pattern": "^#[0-9A-Fa-f]{6}$" },
    "beat_id": { "type": "string", "pattern": "^B[1-9][0-9]*$" },
    "location_id": { "type": "string", "pattern": "^LOC[0-9]{2}$" },
    "background_id": { "type": "string", "pattern": "^BG[0-9]{2}$" },
    "state": { "type": "string", "pattern": "^BS(0[1-9]|1[0-2])$" },
    "assumption": {
      "type": "object",
      "additionalProperties": false,
      "required": ["subject", "value", "reason"],
      "properties": { "subject": { "$ref": "#/$defs/text" }, "value": { "$ref": "#/$defs/text" }, "reason": { "$ref": "#/$defs/text" } }
    },
    "dimension": {
      "type": "object",
      "additionalProperties": false,
      "required": ["value", "basis"],
      "properties": { "value": { "type": ["number", "null"] }, "basis": { "enum": ["production_assumption", "unknown"] } },
      "if": { "properties": { "basis": { "const": "unknown" } } },
      "then": { "properties": { "value": { "type": "null" } } },
      "else": { "properties": { "value": { "type": "number", "exclusiveMinimum": 0 } } }
    },
    "quote": {
      "type": "object",
      "additionalProperties": false,
      "required": ["beat", "field", "quote"],
      "properties": { "beat": { "$ref": "#/$defs/beat_id" }, "field": { "enum": ["location", "time_light", "visual", "purpose", "link"] }, "quote": { "$ref": "#/$defs/text" } }
    },
    "location": {
      "type": "object",
      "additionalProperties": false,
      "required": ["id", "name", "kind", "space", "dimensions", "surfaces", "fixed_equipment", "palette", "assumptions"],
      "properties": {
        "id": { "$ref": "#/$defs/location_id" },
        "name": { "$ref": "#/$defs/text" },
        "kind": { "enum": ["studio", "workshop", "paint_booth", "assembly_bay", "yard", "road", "other"] },
        "space": { "$ref": "#/$defs/text" },
        "dimensions": {
          "type": "object",
          "additionalProperties": false,
          "required": ["length_m", "width_m", "height_m"],
          "properties": { "length_m": { "$ref": "#/$defs/dimension" }, "width_m": { "$ref": "#/$defs/dimension" }, "height_m": { "$ref": "#/$defs/dimension" } }
        },
        "surfaces": { "type": "array", "minItems": 1, "items": { "$ref": "#/$defs/text" } },
        "fixed_equipment": { "$ref": "#/$defs/texts" },
        "palette": { "type": "array", "minItems": 1, "maxItems": 5, "items": { "$ref": "#/$defs/hex" } },
        "assumptions": { "type": "array", "items": { "$ref": "#/$defs/assumption" } }
      }
    },
    "use": {
      "type": "object",
      "additionalProperties": false,
      "required": ["beat", "part"],
      "properties": { "beat": { "$ref": "#/$defs/beat_id" }, "part": { "$ref": "#/$defs/text" } }
    },
    "detail": {
      "type": "object",
      "additionalProperties": false,
      "required": ["text", "evidence", "assumption"],
      "properties": { "text": { "$ref": "#/$defs/text" }, "evidence": { "oneOf": [{ "$ref": "#/$defs/quote" }, { "type": "null" }] }, "assumption": { "type": "boolean" } },
      "if": { "properties": { "evidence": { "type": "null" } } },
      "then": { "properties": { "assumption": { "const": true } } },
      "else": { "properties": { "assumption": { "const": false } } }
    },
    "change": {
      "type": "object",
      "additionalProperties": false,
      "required": ["beats", "kind", "change", "keep"],
      "properties": {
        "beats": { "type": "array", "minItems": 1, "uniqueItems": true, "items": { "$ref": "#/$defs/beat_id" } },
        "kind": { "enum": ["light", "props", "layout", "action"] },
        "change": { "$ref": "#/$defs/text" },
        "keep": { "$ref": "#/$defs/text" }
      }
    },
    "background": {
      "type": "object",
      "additionalProperties": false,
      "required": ["id", "name", "location", "uses", "sharing", "composition", "light", "support", "ground", "details", "must_show", "avoid", "shot_changes", "assumptions"],
      "properties": {
        "id": { "$ref": "#/$defs/background_id" },
        "name": { "$ref": "#/$defs/text" },
        "location": { "$ref": "#/$defs/location_id" },
        "uses": { "type": "array", "minItems": 1, "items": { "$ref": "#/$defs/use" } },
        "sharing": { "$ref": "#/$defs/text" },
        "composition": { "$ref": "#/$defs/text" },
        "light": {
          "type": "object",
          "additionalProperties": false,
          "required": ["description", "evidence", "reason"],
          "properties": { "description": { "$ref": "#/$defs/text" }, "evidence": { "oneOf": [{ "$ref": "#/$defs/quote" }, { "type": "null" }] }, "reason": { "oneOf": [{ "$ref": "#/$defs/text" }, { "type": "null" }] } },
          "if": { "properties": { "evidence": { "type": "null" } } },
          "then": { "properties": { "reason": { "$ref": "#/$defs/text" } } },
          "else": { "properties": { "reason": { "type": "null" } } }
        },
        "support": { "type": "array", "uniqueItems": true, "items": { "enum": ["lift_table", "frame_jig", "engine_stand", "wheel_dolly", "paddock_stand"] } },
        "ground": { "enum": ["dry", "wet", null] },
        "details": { "type": "array", "items": { "$ref": "#/$defs/detail" } },
        "must_show": { "type": "array", "maxItems": 4, "items": { "$ref": "#/$defs/text" } },
        "avoid": { "$ref": "#/$defs/texts" },
        "shot_changes": { "type": "array", "items": { "$ref": "#/$defs/change" } },
        "assumptions": { "type": "array", "items": { "$ref": "#/$defs/assumption" } }
      }
    },
    "unplated": {
      "type": "object",
      "additionalProperties": false,
      "required": ["beat", "part", "location", "reason", "handoff"],
      "properties": {
        "beat": { "$ref": "#/$defs/beat_id" },
        "part": { "$ref": "#/$defs/text" },
        "location": { "oneOf": [{ "$ref": "#/$defs/location_id" }, { "type": "null" }] },
        "reason": { "$ref": "#/$defs/text" },
        "handoff": { "$ref": "#/$defs/text" }
      }
    },
    "conflict_evidence": {
      "type": "object",
      "additionalProperties": false,
      "required": ["path"],
      "properties": {
        "path": { "type": "string", "pattern": "^(beats\\\\.B[1-9][0-9]*\\\\.(location|time_light|visual|purpose|link|situation\\\\.(mode|dry_road|procedures)|subjects\\\\.(motorcycle|model|P[0-9]{2,3})\\\\.(length_m|width_m|height_m)|operations\\\\.F[1-3]|conditions\\\\.M[0-9]+|limits\\\\.L[0-9]{2,3}\\\\.(requires|conditions|procedures|basis))|build_states\\\\.BS(0[1-9]|1[0-2])\\\\.(setting_brief|surface|in_progress))$" },
        "quote": { "$ref": "#/$defs/text" },
        "value": {}
      },
      "oneOf": [{ "required": ["quote"], "not": { "required": ["value"] } }, { "required": ["value"], "not": { "required": ["quote"] } }]
    },
    "conflict": {
      "type": "object",
      "additionalProperties": false,
      "required": ["kind", "beats", "backgrounds", "evidence", "blocking", "note"],
      "properties": {
        "kind": { "enum": ["missing_information", "source_conflict"] },
        "beats": { "type": "array", "uniqueItems": true, "items": { "$ref": "#/$defs/beat_id" } },
        "backgrounds": { "type": "array", "uniqueItems": true, "items": { "$ref": "#/$defs/background_id" } },
        "evidence": { "type": "array", "minItems": 1, "items": { "$ref": "#/$defs/conflict_evidence" } },
        "blocking": { "type": "boolean" },
        "note": { "$ref": "#/$defs/text" }
      }
    },
    "continuity": {
      "type": "object",
      "additionalProperties": false,
      "required": ["backgrounds", "beats", "requirement"],
      "properties": {
        "backgrounds": { "type": "array", "minItems": 1, "uniqueItems": true, "items": { "$ref": "#/$defs/background_id" } },
        "beats": { "type": "array", "minItems": 2, "uniqueItems": true, "items": { "$ref": "#/$defs/beat_id" } },
        "requirement": { "$ref": "#/$defs/text" }
      }
    },
    "data": {
      "type": "object",
      "additionalProperties": false,
      "required": ["locations", "backgrounds", "unplated", "conflicts", "continuity"],
      "properties": {
        "locations": { "type": "array", "items": { "$ref": "#/$defs/location" } },
        "backgrounds": { "type": "array", "items": { "$ref": "#/$defs/background" } },
        "unplated": { "type": "array", "items": { "$ref": "#/$defs/unplated" } },
        "conflicts": { "type": "array", "items": { "$ref": "#/$defs/conflict" } },
        "continuity": { "type": "array", "items": { "$ref": "#/$defs/continuity" } }
      }
    }
  }
}
