    44 => 
    array (
      'id' => 'a3225291-5c56-4350-b84e-21904502517c',
      'namespace' => 'moto',
      'schema_key' => 'MotoScenes',
      'version' => '1.1.1',
      'name' => 'Moto Phase 6 — scenes and continuity (moto-scenes-v1)',
      'schema_content' => '{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://superyacht.local/schemas/MotoScenes",
  "title": "Moto Phase 6 — scenes and continuity (moto-scenes-v1)",
  "description": "One answer of Phase 6 for a custom motorcycle film: the approved beats grouped into scenes, with the continuity each scene starts and ends with, its incoming transition and the work its beats show on parts. Timing, environment assignments, characters, configurations and motorcycle states stay with the beats and are derived by code.",
  "type": "object",
  "additionalProperties": false,
  "required": ["format", "phase", "project_id", "prompt_version", "status", "data", "flags"],
  "properties": {
    "format": { "const": "moto-scenes-v1" },
    "phase": { "const": "6" },
    "project_id": { "$ref": "#/$defs/text" },
    "prompt_version": { "$ref": "#/$defs/text" },
    "status": { "enum": ["ok", "partial", "fail"] },
    "data": { "type": "object" },
    "flags": {
      "description": "Short notes for the reviewer. With status partial, name briefly what blocks, including a blocking conflict carried from the background text, without copying whole conflicts. With status fail, name the fault in the input.",
      "type": "array",
      "items": { "$ref": "#/$defs/text" }
    }
  },
  "allOf": [
    {
      "if": { "properties": { "status": { "const": "fail" } } },
      "then": { "properties": { "data": { "maxProperties": 0 }, "flags": { "minItems": 1 } } },
      "else": { "properties": { "data": { "$ref": "#/$defs/data" } } }
    },
    {
      "if": { "properties": { "status": { "const": "partial" } } },
      "then": { "properties": { "flags": { "minItems": 1 } } }
    }
  ],
  "$defs": {
    "text": { "type": "string", "pattern": "\\\\S" },
    "text_or_null": { "oneOf": [{ "$ref": "#/$defs/text" }, { "type": "null" }] },
    "texts": { "type": "array", "items": { "$ref": "#/$defs/text" } },
    "beat_id": { "type": "string", "pattern": "^B[1-9][0-9]*$" },
    "scene_id": { "type": "string", "pattern": "^SC[0-9]{2}$" },
    "part_id": { "type": "string", "pattern": "^P[0-9]{2,3}$" },
    "light_id": { "type": "string", "pattern": "^P[0-9]{2,3}-L[0-9]{2}$" },
    "evidence": {
      "description": "Evidence paths resolve against this Phase 6 input; do not copy another phase\'s internal evidence paths unchanged or rewrite them by adding a prefix. path: dot-separated keys starting at a top-level key of this input; a list item is named by its id, by its beat or by its zero-based index, e.g. script.beats.B4.link, locations.beats.B11.uses.0.background, design_states.states.BS07.previously_present. A conflict of the background text is cited through its record kept in this input, e.g. locations.conflicts.0.note. quote: text copied verbatim from a text field or an item of a text list. value: the exact value and type of an id, an enumerated value, a number, a boolean, null or structured data; ids and enumerated values are never quoted.",
      "type": "object",
      "additionalProperties": false,
      "required": ["path"],
      "properties": {
        "path": { "type": "string", "pattern": "^(variables|script|beat_times|locations|design_states)(\\\\.[A-Za-z0-9_-]+)+$" },
        "quote": { "$ref": "#/$defs/text" },
        "value": {}
      },
      "oneOf": [
        { "required": ["quote"], "not": { "required": ["value"] } },
        { "required": ["value"], "not": { "required": ["quote"] } }
      ]
    },
    "detached_part": {
      "description": "A part off the motorcycle at the scene\'s build state, read from that state in design_states.states, or held off by the scene\'s work: then being_made while the state lists it in progress, removed when it was on before, otherwise awaiting_install. Without work, being_made: listed in its in_progress. awaiting_install: a finished part waiting to be fitted, listed in both its previously_in_progress (by the workflow\'s convention, work an earlier state does and this one no longer does is finished; this is no proof) and its installed_later; for a part not listed in both, leave detached_parts null or record a conflict. removed: listed in its previously_present.",
      "type": "object",
      "additionalProperties": false,
      "required": ["part", "status"],
      "properties": {
        "part": { "$ref": "#/$defs/part_id" },
        "status": { "enum": ["being_made", "awaiting_install", "removed"] }
      }
    },
    "protection": {
      "description": "One character present at that moment. items: null when the character\'s equipment is unknown, [] when it is established that they wear none, otherwise what they wear for their action, a visor only when their helmet has one.",
      "type": "object",
      "additionalProperties": false,
      "required": ["character", "items"],
      "properties": {
        "character": { "enum": ["builder", "rider"] },
        "items": { "oneOf": [{ "$ref": "#/$defs/texts" }, { "type": "null" }] }
      }
    },
    "continuity": {
      "description": "The staging state at the start or end of the scene beyond the source records. Use null only where the schema allows it; keep every required key. null marks an unestablished or inapplicable detail, [] an established absence. detached_parts and lights_on are null in a scene without a physical build state (BS06–BS12). Protection is always an array; use items: null for a character whose equipment is unknown.",
      "type": "object",
      "additionalProperties": false,
      "required": ["placement", "detached_parts", "lights_on", "surface_condition", "protection", "weather"],
      "properties": {
        "placement": { "$ref": "#/$defs/text_or_null" },
        "detached_parts": { "oneOf": [{ "type": "array", "items": { "$ref": "#/$defs/detached_part" } }, { "type": "null" }] },
        "lights_on": {
          "description": "Ids from design_states.lights that are on, each on a part present at the scene\'s build state and installed and operable no later than that state.",
          "oneOf": [{ "type": "array", "uniqueItems": true, "items": { "$ref": "#/$defs/light_id" } }, { "type": "null" }]
        },
        "surface_condition": { "enum": ["clean", "dusty", "grimy", null] },
        "protection": {
          "description": "The characters present at that moment, each once; [] when no character needs a record then, never to hide what is unknown. A character may enter or leave within the scene.",
          "type": "array",
          "items": { "$ref": "#/$defs/protection" }
        },
        "weather": { "$ref": "#/$defs/text_or_null" }
      }
    },
    "transition": {
      "description": "A match_cut cites the link, visual or sfx of the last beat before the scene or of its first beat. A time_jump cites the time_jump value, other than none, of one of those two beats.",
      "type": "object",
      "additionalProperties": false,
      "required": ["kind", "description", "evidence"],
      "properties": {
        "kind": { "enum": ["cut", "match_cut", "time_jump", "dip"] },
        "description": { "$ref": "#/$defs/text" },
        "evidence": { "type": "array", "items": { "$ref": "#/$defs/evidence" } }
      },
      "if": { "properties": { "kind": { "enum": ["match_cut", "time_jump"] } } },
      "then": { "properties": { "evidence": { "minItems": 1 } } }
    },
    "work_item": {
      "description": "What is done to a part in one beat of the scene and where it is at the start and the end of that work, in beat order. with: the parts worked together with it, sharing its place; parts mounted on a part go with it. make only while the build state lists the part in progress; finish, assemble and paint keep it where it is; test_fit puts on, to try it, a part that has not been on the motorcycle; remove takes off a part that is on; reinstall puts back one that was on before, by its first_state or by earlier work; install puts on for the first time a part the build state has present. A part the build state lists only in progress is being_made wherever it is: it starts off the motorcycle until work of that build state puts it on, may be tried on, taken off and put back, and is never installed; its first test_fit counts as having been on, so it goes back on with reinstall. Within a build state a part starts where its last work left it; at a finished state every part ends on. Evidence comes from the beat: paths under script.beats.<beat>.",
      "type": "object",
      "additionalProperties": false,
      "required": ["beat", "part", "operation", "with", "location_start", "location_end", "evidence"],
      "properties": {
        "beat": { "$ref": "#/$defs/beat_id" },
        "part": { "$ref": "#/$defs/part_id" },
        "operation": { "enum": ["make", "finish", "test_fit", "assemble", "paint", "remove", "install", "reinstall"] },
        "with": { "type": "array", "uniqueItems": true, "items": { "$ref": "#/$defs/part_id" } },
        "location_start": { "enum": ["on_motorcycle", "off_motorcycle"] },
        "location_end": { "enum": ["on_motorcycle", "off_motorcycle"] },
        "evidence": { "type": "array", "minItems": 1, "items": { "$ref": "#/$defs/evidence" } }
      }
    },
    "scene": {
      "type": "object",
      "additionalProperties": false,
      "required": ["id", "beats", "purpose", "set_brief", "continuity_from", "continuity_start", "continuity_end", "transition_in", "work", "assumptions"],
      "properties": {
        "id": { "$ref": "#/$defs/scene_id" },
        "beats": { "type": "array", "minItems": 1, "uniqueItems": true, "items": { "$ref": "#/$defs/beat_id" } },
        "purpose": { "description": "One sentence on what the scene does in the story; never a rewrite of its beats.", "$ref": "#/$defs/text" },
        "set_brief": { "description": "The arrangement of the place the scene needs beyond the background records, as staging notes; never a repeat of the background or a render prompt; null when nothing is needed.", "$ref": "#/$defs/text_or_null" },
        "continuity_from": { "oneOf": [{ "$ref": "#/$defs/scene_id" }, { "type": "null" }] },
        "continuity_start": { "$ref": "#/$defs/continuity" },
        "continuity_end": { "$ref": "#/$defs/continuity" },
        "transition_in": { "oneOf": [{ "$ref": "#/$defs/transition" }, { "type": "null" }] },
        "work": { "type": "array", "items": { "$ref": "#/$defs/work_item" } },
        "assumptions": { "$ref": "#/$defs/texts" }
      }
    },
    "conflict": {
      "description": "Names what it affects: at least one scene or beat; when it names scenes, every beat it names lies in one of them. A conflict about a beat that cannot fit the grouping rules, such as a beat assigned to more than one place, blocks.",
      "type": "object",
      "additionalProperties": false,
      "required": ["scenes", "beats", "evidence", "blocking", "note"],
      "anyOf": [
        { "properties": { "scenes": { "minItems": 1 } } },
        { "properties": { "beats": { "minItems": 1 } } }
      ],
      "properties": {
        "scenes": { "type": "array", "uniqueItems": true, "items": { "$ref": "#/$defs/scene_id" } },
        "beats": { "type": "array", "uniqueItems": true, "items": { "$ref": "#/$defs/beat_id" } },
        "evidence": { "type": "array", "minItems": 1, "items": { "$ref": "#/$defs/evidence" } },
        "blocking": { "type": "boolean" },
        "note": { "$ref": "#/$defs/text" }
      }
    },
    "data": {
      "type": "object",
      "additionalProperties": false,
      "required": ["scenes", "conflicts"],
      "properties": {
        "scenes": { "type": "array", "minItems": 1, "items": { "$ref": "#/$defs/scene" } },
        "conflicts": { "type": "array", "items": { "$ref": "#/$defs/conflict" } }
      }
    }
  }
}
',
      'schema_sha256' => '27c4081b679cecf1011d44e69af073b88193e43fd5329bc29c4918370c40e7cf',
      'source_file' => 'release:moto-phase-6-scenes-v3/MotoScenes.schema.json',
      'json_schema_id' => 'https://superyacht.local/schemas/MotoScenes',
      'json_schema_dialect' => 'https://json-schema.org/draft/2020-12/schema',
      'dependencies' => '[]',
      'status' => 'published',
      'change_note' => 'Release moto-phase-6-scenes-v3 (plan sha256:8dd8c9c6174f4ed00081897152708bc5012df0d327c81c4b6c2beb39262f6f42).',
      'created_by' => 'video:phase-release',
      'created_at' => '2026-11-03 03:54:54',
      'published_at' => '2026-11-03 03:54:54',
    ),
    45 => 
    array (
      'id' => 'a3226939-1b22-4278-9d03-b9fd69fe2a95',
      'namespace' => 'moto',
      'schema_key' => 'MotoShots',
      'version' => '1.1.1',
      'name' => 'Moto Phase 7 — shot list (moto-shots-v1)',
      'schema_content' => '{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://superyacht.local/schemas/MotoShots",
  "title": "Moto Phase 7 — shot list (moto-shots-v1)",
  "description": "One answer of Phase 7 for a custom motorcycle film: the shots of every approved scene as data, with the scene plan\'s work each shows, from which code builds the image and video prompts. Timing, environment sources, reference images, absent parts, limits, cards and readiness are derived by code.",
  "type": "object",
  "additionalProperties": false,
  "required": ["format", "phase", "project_id", "prompt_version", "status", "data", "flags"],
  "properties": {
    "format": { "const": "moto-shots-v1" },
    "phase": { "const": "7" },
    "project_id": { "$ref": "#/$defs/text" },
    "prompt_version": { "$ref": "#/$defs/text" },
    "status": { "enum": ["ok", "partial", "fail"] },
    "data": { "type": "object" },
    "flags": {
      "description": "Short notes for the reviewer. With status partial, name briefly what blocks, without copying whole conflicts. With status fail, name the fault in the input.",
      "type": "array",
      "items": { "$ref": "#/$defs/text" }
    }
  },
  "allOf": [
    {
      "if": { "properties": { "status": { "const": "fail" } } },
      "then": { "properties": { "data": { "maxProperties": 0 }, "flags": { "minItems": 1 } } },
      "else": { "properties": { "data": { "$ref": "#/$defs/data" } } }
    },
    {
      "if": { "properties": { "status": { "const": "partial" } } },
      "then": { "properties": { "flags": { "minItems": 1 } } }
    }
  ],
  "$defs": {
    "text": { "type": "string", "pattern": "\\\\S" },
    "text_or_null": { "oneOf": [{ "$ref": "#/$defs/text" }, { "type": "null" }] },
    "texts": { "type": "array", "items": { "$ref": "#/$defs/text" } },
    "beat_id": { "type": "string", "pattern": "^B[1-9][0-9]*$" },
    "scene_id": { "type": "string", "pattern": "^SC[0-9]{2}$" },
    "shot_id": { "type": "string", "pattern": "^SC[0-9]{2}_SH[0-9]{2}$" },
    "part_id": { "type": "string", "pattern": "^P[0-9]{2,3}$" },
    "background_id": { "type": "string", "pattern": "^BG[0-9]{2}$" },
    "configuration_id": { "type": "string", "pattern": "^P[0-9]{2,3}-K[0-9]{2}$" },
    "ms": { "type": "integer", "minimum": 0 },
    "evidence": {
      "description": "Evidence paths resolve against this Phase 7 input; do not copy another phase\'s internal evidence paths unchanged or rewrite them by adding a prefix. path: dot-separated keys starting at a top-level key of this input; a list item is named by its id, by its beat or by its zero-based index, e.g. beats.B4.visual, scenes.SC03.continuity_start.placement, design_states.BS07.in_progress. quote: text copied verbatim from a text field or an item of a text list. value: the exact value and type of an id, an enumerated value, a number, a boolean, null or structured data; ids and enumerated values are never quoted.",
      "type": "object",
      "additionalProperties": false,
      "required": ["path"],
      "properties": {
        "path": { "type": "string", "pattern": "^(film|story|characters|scenes|beats|places|backgrounds|motorcycle|parts|features|limits|design_states|views|render_capabilities)(\\\\.[A-Za-z0-9_-]+)+$" },
        "quote": { "$ref": "#/$defs/text" },
        "value": {}
      },
      "oneOf": [
        { "required": ["quote"], "not": { "required": ["value"] } },
        { "required": ["value"], "not": { "required": ["quote"] } }
      ]
    },
    "coverage": {
      "description": "One part of a beat the shot shows, with the screen time it takes. result_at_ms is clip time, inside this part\'s span of the kept interval, or null when the part shows no result.",
      "type": "object",
      "additionalProperties": false,
      "required": ["beat", "part", "used_duration_ms", "result_at_ms"],
      "properties": {
        "beat": { "$ref": "#/$defs/beat_id" },
        "part": { "enum": ["whole", "opening", "middle", "closing"] },
        "used_duration_ms": { "type": "integer", "exclusiveMinimum": 0 },
        "result_at_ms": { "oneOf": [{ "$ref": "#/$defs/ms" }, { "type": "null" }] }
      }
    },
    "shown_part": {
      "description": "A part in frame and how it is shown at the first frame. For a part a work item of the shot moves or keeps in place, the presentation it has at the start of the first such item (scenes[].work[].presentations); for any other part the work holds, the presentation the work shown so far left it in, carried through every later beat of the same build state; otherwise what the build state has: installed on the motorcycle, being_made in progress, awaiting_install or removed as the state lists it. drawing or model before a physical motorcycle exists. The presentation describes how the part is shown, never where it is: a part being_made may be on the motorcycle while it is tried on; where it is comes from the work (location_start, location_end).",
      "type": "object",
      "additionalProperties": false,
      "required": ["part", "presentation"],
      "properties": {
        "part": { "$ref": "#/$defs/part_id" },
        "presentation": { "enum": ["installed", "being_made", "awaiting_install", "removed", "drawing", "model"] }
      }
    },
    "person": {
      "type": "object",
      "additionalProperties": false,
      "required": ["character", "view"],
      "properties": {
        "character": { "enum": ["builder", "rider"] },
        "view": { "enum": ["hands", "back", "silhouette"] }
      }
    },
    "camera": {
      "type": "object",
      "additionalProperties": false,
      "required": ["target", "target_part", "scale", "lens_mm", "height_m", "distance_m", "azimuth_deg", "elevation_deg", "move", "move_value", "move_unit", "start_pose", "end_pose"],
      "properties": {
        "target": { "enum": ["motorcycle", "part", "person", "place", "drawing", "model", "screen", "tool"] },
        "target_part": { "oneOf": [{ "$ref": "#/$defs/part_id" }, { "type": "null" }] },
        "scale": { "enum": ["extreme_wide", "wide", "medium", "close", "macro"] },
        "lens_mm": { "type": "number", "minimum": 8, "maximum": 800 },
        "height_m": { "type": ["number", "null"], "minimum": 0 },
        "distance_m": { "type": ["number", "null"], "exclusiveMinimum": 0 },
        "azimuth_deg": { "type": ["number", "null"], "minimum": 0, "exclusiveMaximum": 360 },
        "elevation_deg": { "type": ["number", "null"], "minimum": -90, "maximum": 90 },
        "move": { "enum": ["static", "push", "pull", "slide", "pan", "tilt", "orbit", "crane", "track", "drone"] },
        "move_value": { "type": ["number", "null"] },
        "move_unit": { "enum": ["m", "deg", null] },
        "start_pose": { "$ref": "#/$defs/text" },
        "end_pose": { "$ref": "#/$defs/text" }
      },
      "allOf": [
        {
          "if": { "properties": { "move": { "const": "static" } } },
          "then": { "properties": { "move_value": { "type": "null" }, "move_unit": { "type": "null" } } },
          "else": { "properties": { "move_value": { "type": "number" }, "move_unit": { "enum": ["m", "deg"] } } }
        },
        {
          "if": { "properties": { "target": { "const": "part" } } },
          "then": { "properties": { "target_part": { "$ref": "#/$defs/part_id" } } },
          "else": { "properties": { "target_part": { "type": "null" } } }
        }
      ]
    },
    "environment": {
      "type": "object",
      "additionalProperties": false,
      "required": ["mode", "background", "request"],
      "properties": {
        "mode": { "enum": ["background", "unplated", "request"] },
        "background": { "oneOf": [{ "$ref": "#/$defs/background_id" }, { "type": "null" }] },
        "request": { "$ref": "#/$defs/text_or_null" }
      },
      "allOf": [
        {
          "if": { "properties": { "mode": { "const": "background" } } },
          "then": { "properties": { "background": { "$ref": "#/$defs/background_id" }, "request": { "type": "null" } } }
        },
        {
          "if": { "properties": { "mode": { "const": "unplated" } } },
          "then": { "properties": { "background": { "type": "null" }, "request": { "type": "null" } } }
        },
        {
          "if": { "properties": { "mode": { "const": "request" } } },
          "then": { "properties": { "request": { "$ref": "#/$defs/text" } } }
        }
      ]
    },
    "reference_need": {
      "description": "What the keyframe needs to stay faithful. identity: the motorcycle as a whole, target null. design: a part of the shot, target its id. environment: the shot\'s background, target its id, or null for a requested background. continuity: an earlier shot of the same continuous action — the same scene, or the scene the scene plan continues from — target its id.",
      "type": "object",
      "additionalProperties": false,
      "required": ["kind", "target", "purpose"],
      "properties": {
        "kind": { "enum": ["identity", "design", "environment", "continuity"] },
        "target": { "oneOf": [{ "type": "string", "pattern": "^(P[0-9]{2,3}|BG[0-9]{2}|SC[0-9]{2}_SH[0-9]{2})$" }, { "type": "null" }] },
        "purpose": { "$ref": "#/$defs/text" }
      }
    },
    "shot": {
      "type": "object",
      "additionalProperties": false,
      "required": ["id", "scene", "coverage", "purpose", "reveal", "parts", "work", "configurations", "people", "camera", "first_frame", "action", "result", "end_frame", "continuity", "environment", "reference_needs", "render_duration_ms", "mode", "used_start_ms", "used_duration_ms", "links", "assumptions"],
      "properties": {
        "id": { "$ref": "#/$defs/shot_id" },
        "scene": { "$ref": "#/$defs/scene_id" },
        "coverage": { "type": "array", "minItems": 1, "items": { "$ref": "#/$defs/coverage" } },
        "purpose": { "$ref": "#/$defs/text" },
        "work": {
          "description": "The ids of the work items of the scene plan (scenes[].work[].id) the shot shows happening, in the scene plan\'s order within the shot and from shot to shot, never returning to an earlier item; each in a covered beat, with its part in parts. Every work item is shown by at least one shot. The shot never decides a removal, fitting or making of its own.",
          "type": "array",
          "uniqueItems": true,
          "items": { "type": "string", "pattern": "^SC[0-9]{2}-W[1-9][0-9]*$" }
        },
        "reveal": {
          "description": "How much of the motorcycle the shot shows, on the scale of the script\'s reveal. A shot that covers several beats uses a reveal allowed by every covered beat. Shape and detail do not substitute for each other.",
          "enum": ["none", "fragment", "shape", "detail", "whole"]
        },
        "parts": { "type": "array", "items": { "$ref": "#/$defs/shown_part" } },
        "configurations": {
          "description": "For each part shown as installed whose position is established by the covered beats or a build-state exception, provide one configuration in both start and end. Start is the first frame; end is after the action.",
          "type": "object",
          "additionalProperties": false,
          "required": ["start", "end"],
          "properties": {
            "start": { "type": "array", "uniqueItems": true, "items": { "$ref": "#/$defs/configuration_id" } },
            "end": { "type": "array", "uniqueItems": true, "items": { "$ref": "#/$defs/configuration_id" } }
          }
        },
        "people": { "type": "array", "items": { "$ref": "#/$defs/person" } },
        "camera": { "$ref": "#/$defs/camera" },
        "first_frame": { "$ref": "#/$defs/text" },
        "action": { "$ref": "#/$defs/text" },
        "result": { "$ref": "#/$defs/text" },
        "end_frame": { "$ref": "#/$defs/text_or_null" },
        "continuity": {
          "description": "changes: what changes during the shot. carries: the state the next shot starts from.",
          "type": "object",
          "additionalProperties": false,
          "required": ["changes", "carries"],
          "properties": {
            "changes": { "$ref": "#/$defs/texts" },
            "carries": { "$ref": "#/$defs/texts" }
          }
        },
        "environment": { "$ref": "#/$defs/environment" },
        "reference_needs": { "type": "array", "items": { "$ref": "#/$defs/reference_need" } },
        "render_duration_ms": { "type": "integer", "exclusiveMinimum": 0 },
        "mode": { "enum": ["image_to_video", "first_last"] },
        "used_start_ms": { "$ref": "#/$defs/ms" },
        "used_duration_ms": { "type": "integer", "exclusiveMinimum": 0 },
        "links": {
          "type": "object",
          "additionalProperties": false,
          "required": ["match_from", "motif", "repeat_reason"],
          "properties": {
            "match_from": { "oneOf": [{ "$ref": "#/$defs/shot_id" }, { "type": "null" }] },
            "motif": { "$ref": "#/$defs/text_or_null" },
            "repeat_reason": { "$ref": "#/$defs/text_or_null" }
          }
        },
        "assumptions": { "$ref": "#/$defs/texts" }
      },
      "if": { "properties": { "mode": { "const": "first_last" } } },
      "then": { "properties": { "end_frame": { "$ref": "#/$defs/text" } } },
      "else": { "properties": { "end_frame": { "type": "null" } } }
    },
    "conflict": {
      "description": "Names at least one shot or beat it affects.",
      "type": "object",
      "additionalProperties": false,
      "required": ["shots", "beats", "evidence", "blocking", "note"],
      "anyOf": [
        { "properties": { "shots": { "minItems": 1 } } },
        { "properties": { "beats": { "minItems": 1 } } }
      ],
      "properties": {
        "shots": { "type": "array", "uniqueItems": true, "items": { "$ref": "#/$defs/shot_id" } },
        "beats": { "type": "array", "uniqueItems": true, "items": { "$ref": "#/$defs/beat_id" } },
        "evidence": { "type": "array", "minItems": 1, "items": { "$ref": "#/$defs/evidence" } },
        "blocking": { "type": "boolean" },
        "note": { "$ref": "#/$defs/text" }
      }
    },
    "data": {
      "type": "object",
      "additionalProperties": false,
      "required": ["shots", "conflicts"],
      "properties": {
        "shots": { "type": "array", "minItems": 1, "items": { "$ref": "#/$defs/shot" } },
        "conflicts": { "type": "array", "items": { "$ref": "#/$defs/conflict" } }
      }
    }
  }
}
',
      'schema_sha256' => '9275ef59c80a6f3b0cf0716c827afa6baf6b7609a6846b802ca743490ee811d3',
      'source_file' => 'release:moto-phase-7-shots-v3/MotoShots.schema.json',
      'json_schema_id' => 'https://superyacht.local/schemas/MotoShots',
      'json_schema_dialect' => 'https://json-schema.org/draft/2020-12/schema',
      'dependencies' => '[]',
      'status' => 'published',
      'change_note' => 'Release moto-phase-7-shots-v3 (plan sha256:88b4b01298153ffa287eee6ef9e4b2876665a7ff757bb8550e3616e8b9ac0e59).',
      'created_by' => 'video:phase-release',
