    "departures": [{"id": "D1", "from_id": "X04", "method": "RELOCATE", "result": "…"}],
    "innovations": [{"id": "N1", "name": "…", "what": "…", "why_new": "…", "plausibility": "…", "visible": "both"}],
    "silhouette": "…",
